(function(){var d={"Contabilidade de Instituições Financeiras (COSIF)::Aula 00":{"questoesPdf":[{"title":"Questões Extraídas — Estrutura e Conceitos do COSIF · Aula 00 (12 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF · Aula 00 · Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 00 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 00 — <b>Estrutura e Conceitos do COSIF</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 00 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Contador Nossa Caixa · 2012\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"As normas e procedimentos, bem como as\\ndemonstrações financeiras padronizadas previstas no Plano Contábil das Instituições do\\nSistema Financeiro Nacional - Cosif, são de uso obrigatório, EXCETO para:\",\"c\":\"financeiras e, portanto, não estão obrigadas a usar as normas do Cosif.\",\"o\":[\"Caixas econômicas;\",\"Sociedades de crédito ao microempreendedor;\",\"Empresas em liquidação extrajudicial;\",\"Administradoras de imóveis das instituições financeiras;\",\"Bancos de investimentos.\"],\"g\":3},{\"_id\":1,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista BACEN Área 3 · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A escrituração contábil e elaboração de\\nDemonstrativos Financeiros de Instituições Financeiras devem observar os princípios\\nfundamentais da contabilidade. Com base nestes princípios, o reconhecimento da receita de\\njuros de empréstimos concedidos deve se dar:\",\"c\":\"da competência. Sendo assim, o reconhecimento de receita de juros de empréstimo deve ser dar no momento em que o fato gerador ocorre. No caso dos empréstimos, o fato gerador é o transcurso do tempo, ou seja, a cada mês que passa ocorre um novo fato gerador o qual trará ao tomador do empréstimo a obrigação de pagar os juros daquele período transcorrido à instituição financeira.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa\\n\\nLembrem-se: As instituições que sujeitas às regras do Cosif devem “registrar as receitas e despesas no período em que elas ocorrem e não na data do efetivo ingresso ou desembolso, em respeito ao regime de competência.”\",\"o\":[\"somente no momento da liberação do empréstimo, com os devidos lançamentos de provisão para eventuais perdas.\",\"ao longo da duração do empréstimo, sendo apropriado período a período.\",\"somente no momento do recebimento do empréstimo, revertendo eventuais provisões de perdas que não ocorreram.\",\"parte na liberação do empréstimo e parte no recebimento, de acordo com o nível de provisão estabelecido pela administração do banco.\",\"somente no vencimento, caso o empréstimo for pago.\"],\"g\":1},{\"_id\":2,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista BACEN Área 3 · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No momento em que há uma diminuição do nível de\\ndepósito compulsório que um banco mantém no Banco Central, o balanço patrimonial desse\\nbanco sofrerá as seguintes mudanças:\",\"c\":\"aplicação da lógica contábil. Primeiramente, precisamos saber que os depósitos compulsórios correspondem a valores mantidos “obrigatoriamente” pelas instituições financeiras no Banco Central do Brasil. Eles são um dos instrumentos que o BACEN possui para fazer política monetária. Certamente você irá estudar isso na disciplina de Macroeconomia. Para resolver a questão, o que você precisa ter em mente é que esses depósitos compulsórios são ativos da instituição, pois, se ela teve de depositá-los obrigatoriamente no BACEN, uma hora eles serão devolvidos, concordam? Assim, em algum momento oportuno esses depósitos, os quais correspondem a direitos das instituições junto ao BACEN, serão reavidos. Pois bem, caso o BACEN devolva a totalidade dos valores dos compulsórios à instituição, esse direito da instituição junto ao BACEN não existirá mais e, consequentemente, a conta do ativo terá seu saldo zerado (diminuição de uma conta do ativo). E para onde irá esse valor recebido dos compulsórios? Certamente para outra conta do ativo, pois é nele que a instituição registra todos os seus bens e direitos (aumento de uma conta do ativo). Percebam que estamos diante de um Fato Permutativo, conforme vimos em nossa aula, o qual não altera o valor total do Ativo.\",\"o\":[\"aumento de uma conta do Passivo e diminuição de outra conta do Passivo, ficando o valor do Passivo Total inalterado.\",\"aumento de uma conta do Ativo e diminuição de outra conta do Ativo, ficando o valor do Ativo Total inalterado.\",\"aumento de uma conta do Ativo e aumento de uma conta do Passivo.\",\"diminuição de uma conta do Ativo e diminuição de uma conta do Passivo.\",\"aumento de uma conta do Passivo e diminuição de uma conta do Patrimônio Líquido.\"],\"g\":1},{\"_id\":3,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista BACEN Área 3 · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No que concerne a contas e grupo de contas\\napresentadas no Cosif, plano contábil das instituições do sistema financeiro nacional, são\\ncontas APENAS de RESULTADO:\",\"c\":\"recorrentemente. Reitero mais uma vez: não deixem de memorizar o quadro (visto nesta aula) com as contas até os SUBGRUPOS!\\n\\nA única opção com contas apenas de resultados é a LETRA e.\",\"o\":[\"Rendas com Títulos e Valores Mobiliários e Instrumentos Financeiros Derivativos; Despesas de Obrigações por Empréstimos e Repasses; Despesas de Captação; Provisão para Passivos Contingentes.\",\"Resultado de Transações com Títulos e Valores Mobiliários; Rendas a Receber; Rendas com Títulos e Valores Mobiliários e Instrumentos Financeiros Derivativos; Despesas de Obrigações por Empréstimos e Repasses.\",\"Despesas Obrigações por Empréstimos e Repasses; Despesas de Captação; Despesa Antecipada; Rendas com Títulos e Valores Mobiliários e Instrumentos Financeiros Derivativos.\",\"Despesas de Obrigações por Empréstimos e Repasses; Despesas de Captação; Lucro na Transação com Valores e Bens; Rendas Antecipadas.\",\"Rendas com Títulos e Valores Mobiliários e Instrumentos Financeiros Derivativos; Despesas de Obrigações por Empréstimos e Repasses; Despesas de Captação; Lucro na Transação com Valores e Bens.\"],\"g\":4},{\"_id\":4,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista BACEN Área 3 · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A escrituração contábil e a elaboração de\\nDemonstrativos Financeiros de Instituições Financeiras devem observar os princípios\\nfundamentais da contabilidade.\\n\\nCom base nestes princípios, o reconhecimento da despesa de juros de um CDB emitido\\n(depósito a prazo) deve se dar:\",\"c\":\"também estão sujeitas à observância do princípio da competência. Sendo assim, o reconhecimento de receita de juros de empréstimo deve ser dar no momento em que o fato gerador ocorre. No caso dos CDB’s, o fato gerador é o transcurso do tempo, ou seja, a cada mês que passa ocorre um novo fato gerador o qual trará à instituição financeira a obrigação de pagar os juros (rendimentos) daquele período transcorrido ao cliente.\\n\\nLembrem-se: As instituições que sujeitas às regras do Cosif devem “registrar as receitas e despesas no período em que elas ocorrem e não na data do efetivo ingresso ou desembolso, em respeito ao regime de competência.\",\"o\":[\"somente no vencimento do CDB.\",\"somente no momento da emissão do CDB.\",\"somente no momento do vencimento do CDB.\",\"parte na emissão do CDB e parte no vencimento, de acordo com o nível de conservadorismo da administração do banco.\",\"ao longo da duração do CDB, sendo apropriado período a período. BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa\"],\"g\":4},{\"_id\":5,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista BACEN Área 4 · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No que diz respeito a contas e grupo de contas\\napresentadas no Cosif, plano contábil das instituições do sistema financeiro nacional, são\\ncontas APENAS do PASSIVO:\",\"c\":\"treinar agora para não errar na prova. Todas as contas que constam na letra a são contas do PASSIVO. Não tem desculpa para não acertar esse tipo de questão na prova!\",\"o\":[\"Obrigações por Operações Compromissadas; Obrigações por Empréstimos e repasses; Outras Obrigações; Depósitos.\",\"Depósitos; Aplicações Interfinanceiras de Liquidez; Outras Obrigações; Despesas de Obrigações por Empréstimos e Repasses.\",\"Depósitos; Obrigações por Operações Compromissadas; Obrigações por Empréstimos e repasses; Despesa Antecipada.\",\"Obrigações por Obrigações Compromissadas; Disponibilidades; Outras Obrigações; Depósitos.\",\"Operações de Crédito; Obrigações por Operações Compromissadas; Obrigações por Empréstimos e repasses; Provisão para Passivos Contingentes.\"],\"g\":0},{\"_id\":6,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista BACEN Área 4 · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No momento em que um banco concede empréstimo\\na um cliente, os grupos de contas dos seus demonstrativos financeiros terão os seguintes\\nimpactos:\",\"c\":\"uma instituição financeira concede um novo empréstimo a um cliente, há um novo direito seu registrado no ativo (aumento do ativo). Esse direito corresponde à obrigatoriedade de o cliente pagar à instituição todo o valor devido dos empréstimos, incluindo os juros e as taxas da operação. Por outro lado, o dinheiro do empréstimo é entregue ao seu cliente. Mas onde o cliente tem conta? Na própria instituição! Ou seja, a conta do cliente está registrada no passivo da instituição financeira, pois há uma obrigação de a instituição devolver o dinheiro depositado quando o cliente fizer um saque, por exemplo. Sendo assim, há aumento também do valor do Passivo na mesma proporção do aumento do Ativo, sem, inicialmente, modificar o patrimônio. Trata-se de um Fato Contábil Permutativo.\",\"o\":[\"diminuição do Passivo e diminuição do Ativo. BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa\",\"aumento do Ativo e aumento do Patrimônio Líquido (via resultado).\",\"aumento do Ativo e aumento do Passivo.\",\"aumento da Receita e diminuição de Despesas, porém o resultado é positivo.\",\"diminuição do Passivo e aumento do Patrimônio Líquido.\"],\"g\":2},{\"_id\":7,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista BACEN Supervisão · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Abaixo são apresentadas assertivas relacionadas\\naos procedimentos específicos previstos no Cosif, relativos à escrituração.\\n\\nAssinale a opção que contém a afirmativa incorreta:\",\"c\":\"escrituração:\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa\\n\\nAdotar métodos e critérios uniformes no tempo. As modificações relevantes devem ser evidenciadas em notas explicativas, quantificando-se os efeitos nas demonstrações financeiras;\\n\\nRegistrar as receitas e despesas no período em que elas ocorrem e não na data do efetivo ingresso ou desembolso, em respeito ao regime de competência;\\n\\nFazer a apropriação mensal das rendas, inclusive mora, receitas, ganhos, lucros, despesas, perdas e prejuízos, independentemente da apuração de resultado a cada seis meses;\\n\\nApurar os resultados em períodos fixos de tempo, observando os períodos de 1º de janeiro a 30 de junho e 1º de julho a 31 de dezembro;\\n\\nProceder às devidas conciliações dos títulos contábeis com os respectivos controles analíticos e mantê-las atualizadas, conforme determinado nas seções próprias deste Plano, devendo a respectiva documentação ser arquivada por, pelo menos, um ano.\\n\\nVejam que a banca tentou induzir o candidato ao erro com uma apuração de resultados trimestral. Atenção!\",\"o\":[\"Adotar métodos e critérios uniformes no tempo, sendo que as modificações relevantes devem ser evidenciadas em notas explicativas, quantificando os efeitos nas demonstrações financeiras, quando aplicável.\",\"Apurar os resultados em períodos fixos de tempo, observando os períodos de 1º de janeiro a 31 de março, de 1º de abril a 30 de junho, de 1º de julho a 30 de setembro, e de 1º de outubro a 31 de dezembro.\",\"Fazer a apropriação mensal das rendas, inclusive mora, receitas, ganhos, lucros, despesas, perdas e prejuízos, independentemente da apuração de resultado a cada seis meses.\",\"Registrar as receitas e despesas no período em que elas ocorrem e não na data do efetivo ingresso ou desembolso, em respeito ao regime de competência.\",\"Proceder às devidas conciliações dos títulos contábeis com os respectivos controles analíticos e mantê-las atualizadas, devendo a respectiva documentação ser arquivada por, pelo menos, um ano.\"],\"g\":1},{\"_id\":8,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista BACEN Supervisão · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Relativamente aos critérios para avaliação e\\napropriação contábil nas operações com taxas prefixadas, avalie o acerto das afirmações\\nadiante e marque com V as verdadeiras e com F as falsas, em seguida, marque a opção\\ncorreta.\\n\\n( ) As rendas e os encargos dessas operações são apropriados mensalmente, a crédito ou a\\ndébito das contas efetivas de receitas ou despesas, conforme o caso, em razão da fluência de\\nseus prazos, admitindo-se a apropriação em períodos inferiores a um mês.\\n\\n( ) As rendas e os encargos proporcionais aos dias decorridos no mês da contratação da\\noperação devem ser apropriados dentro do\\npróprio mês, pro rata temporis, considerando-se o número de dias corridos.\\n( ) A apropriação das rendas e dos encargos mensais dessas operações faz-se mediante a\\nutilização do método exponencial, admitindo-se a apropriação segundo o método linear\\nnaquelas contratadas com cláusula de juros simples.\",\"c\":\"As operações ativas e passivas contratadas com rendas e encargos prefixados contabilizam- se pelo valor presente, registrando-se as rendas e os encargos a apropriar em subtítulo de uso interno do próprio título ou subtítulo contábil utilizado para registrar a operação;\\n\\nAs rendas e os encargos dessas operações são apropriados mensalmente, a crédito ou a débito das contas efetivas de receitas ou despesas, conforme o caso, em razão da fluência de seus prazos, admitindo-se a apropriação em períodos inferiores a um mês;\\n\\nAs rendas e os encargos proporcionais aos dias decorridos no mês da contratação da operação devem ser apropriados dentro do próprio mês, \\\"pro rata temporis\\\", considerando-se o número de dias corridos;\\n\\nA apropriação das rendas e dos encargos mensais dessas operações faz-se mediante a utilização do método exponencial, admitindo-se a apropriação segundo o método linear naquelas contratadas com cláusula de juros simples. (Lembram-se dos juros compostos e dos juros simples que vimos no início da nossa aula? Pois bem. O método exponencial corresponde aos juros compostos, e o método linear corresponde aos juros simples.).\\n\\nPortanto, todas as alternativas estão corretas.\",\"o\":[\"F, V, V\",\"V, V, F\",\"V, F, F\",\"V, V ,V\",\"F, F, V BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa\"],\"g\":3},{\"_id\":9,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista BACEN Supervisão · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Relativamente aos critérios que devem ser\\nobservados para avaliação e apropriação contábil das operações com taxas pós-fixadas ou\\nflutuantes, assinale o acerto das afirmações adiante e marque com V as verdadeiras e com F\\nas falsas, em seguida, marque a opção correta.\\n\\n( ) As operações ativas e passivas contratadas com rendas e encargos pós-fixados ou\\nflutuantes contabilizam-se pelo valor do principal, a débito ou a crédito das contas que as\\nregistram. Essas mesmas contas acolhem os juros e os ajustes mensais decorrentes das\\nvariações da unidade de correção ou dos encargos contratados, no caso de taxas flutuantes.\\n( ) As rendas e os encargos proporcionais aos dias decorridos no mês da contratação da\\noperação devem ser apropriados dentro do próprio mês, pro rata temporis, considerando-se\\no número de dias corridos.\\n\\n( ) A apropriação das rendas e dos encargos mensais dessas operações faz-se mediante a\\nutilização do método exponencial, admitindo-se a apropriação segundo o método linear\\nnaquelas contratadas com cláusula de juros simples, segundo o indexador utilizado para\\ncorreção do mês seguinte em relação ao mês corrente, pro rata temporis no caso de\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF\\nCarlos Roberto Correa\\n\\noperações com taxas pós-fixadas, ou com observância às taxas contratadas, no caso de\\noperações com encargos flutuantes.\",\"c\":\"o que diz o Cosif com relação aos critérios que devem ser observados para avaliação e apropriação contábil das operações com taxas pós-fixadas ou flutuantes:\\n\\na) As operações ativas e passivas contratadas com rendas e encargos pós-fixados ou\\n\\nflutuantes contabilizam-se pelo valor do principal, a débito ou a crédito das contas que as registram. Essas mesmas contas acolhem os juros e os ajustes mensais decorrentes das variações da unidade de correção ou dos encargos contratados, no caso de taxas flutuantes;\\n\\nb) As rendas e os encargos dessas operações são apropriados mensalmente, a crédito ou\\n\\na débito das contas efetivas de receitas ou despesas, conforme o caso, em razão da fluência de seus prazos, admitindo-se a apropriação em períodos inferiores a um mês;\\n\\nc) As rendas e os encargos proporcionais aos dias decorridos no mês da contratação da\\n\\noperação devem ser apropriados dentro do próprio mês, \\\"pro rata temporis\\\", considerando-se o número de dias corridos;\\n\\nd) A apropriação das rendas e dos encargos mensais dessas operações faz-se mediante a\\n\\nutilização do método exponencial, admitindo-se a apropriação segundo o método linear naquelas contratadas com cláusula de juros simples, segundo o indexador utilizado para correção do mês seguinte em relação ao mês corrente, \\\"pro rata temporis\\\" no caso de operações com taxas pós-fixadas, ou com observância às taxas contratadas, no caso de operações com encargos flutuantes;\\n\\ne) As operações ativas e passivas contratadas com cláusula de reajuste segundo a\\n\\nvariação da Unidade Padrão de Capital (UPC), atualizam-se mensalmente, \\\"pro rata temporis\\\", com base na variação da OTN. Caso ocorram liquidações no transcorrer do trimestre, a instituição deve proceder aos estornos pertinentes.\\n\\nPortanto, todas as alternativas estão corretas. Pessoal, vocês devem estar achando muito repetitivo na aula o que diz o Cosif com relação aos critérios que devem ser observados para avaliação e apropriação contábil das operações com taxas pós-fixadas ou flutuantes e com taxas prefixadas. Saibam que estou fazendo isso e forma proposital, com o intuito de, após esta aula, você não esquecerem mais esses conceitos.\",\"o\":[\"V, V, F\",\"F, V, F\",\"F, V, V\",\"F, F, V\",\"V, V, V\"],\"g\":4},{\"_id\":10,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"CESGRANRIO PB (BNDES) BNDES Contabilidade · 2007\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"As instituições financeiras\\nnacionais possuem um Plano de Contas Padronizado denominado Cosif (Plano Contábil das\\nInstituições do Sistema Financeiro Nacional).\\n\\nUma das características básicas do Cosif é a de:\",\"c\":\"a) Essa vedação corresponde a uma determinação trazida pela Lei 4.595/64, e não pelo\\n\\nCosif;\\n\\nb) As instituições financeiras e demais instituições fiscalizadas pelo BACEN estão\\n\\ndispensadas da obrigatoriedade de elaboração e publicação da Demonstração das Origens e Aplicações de Recursos (DOAR), desde a data-base de 31 de dezembro de 2008. Veremos isso na aula sobre demonstrações financeiras.\\n\\nc) Perfeito. Este é o nosso gabarito. É exatamente isso que vimos nesta aula como\\n\\ncaracterística básica do Cosif.\\n\\nd) Simplesmente não há essa determinação no Cosif.\\n\\ne) Essa é uma determinação trazida pela Lei 4.595/64, e não pelo Cosif.\",\"o\":[\"vedar às instituições financeiras conceder empréstimos ou adiantamentos: a seus diretores e membros dos conselhos consultivos ou administrativo, fiscais e semelhantes, bem como aos respectivos cônjuges; aos parentes, até o 2º grau, das pessoas a que se refere o inciso anterior; às pessoas físicas ou jurídicas que participem de seu capital, com mais de 10% (dez por cento), salvo autorização específica do Banco Central do Brasil.\",\"estabelecer que, no encerramento de cada exercício social, a instituição deverá elaborar, com base em comprovantes hábeis e legais, a escrituração das seguintes demonstrações financeiras, exprimindo com clareza a situação do patrimônio da instituição financeira e as mutações ocorridas no exercício: Balanço Patrimonial; Balancetes e balanços mensais, Demonstração do Resultado do Exercício e Demonstração das Origens e Aplicações de Recursos.\",\"determinar que a escrituração, fundamentada em comprovantes hábeis para a perfeita validade de atos e fatos administrativos, deve ser completa, mantendo-se em registros BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa permanentes todos os atos e fatos administrativos que modifiquem ou venham a modificar, imediatamente ou não, a composição patrimonial da instituição financeira.\",\"impor que as instituições financeiras deverão manter registros específicos de todas as operações que alterem o patrimônio da entidade, incluindo convênios com outras instituições, sendo estes expressamente autorizados pelo Banco Central do Brasil, visando a preservar a moeda nacional e a manter Reservas Bancárias suficientes para atender ao público investidor.\",\"recomendar que os serviços de compensação de cheques e outros papéis sofram permanente vigilância por parte do Banco Central do Brasil em virtude do risco que podem causar à saúde financeira do Sistema Financeiro Nacional e à fidedignidade dos registros contábeis das instituições que a representam.\"],\"g\":2},{\"_id\":11,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Ana (BACEN) BACEN Área 4 Contabilidade e Finanças · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item a\\nseguir, de acordo com o Plano Contábil das Instituições do Sistema Financeiro Nacional\\n(Cosif).\\n\\nAs instituições integrantes do sistema financeiro nacional devem, mensalmente, apropriar as\\nrendas, como mora, ganhos, receitas, despesas e perdas e, semestralmente, apurar os\\nresultados do período.\",\"c\":\"inclusive mora, receitas, ganhos, lucros, despesas, perdas e prejuízos, independentemente da apuração de resultado a cada seis meses.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 01":{"questoesPdf":[{"title":"Questões Extraídas — Normas Básicas e Estrutura Contábil · Aula 01 (10 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF · Aula 01 · Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 01 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 01 — <b>Normas Básicas e Estrutura Contábil</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 01 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista Bacen · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Apresentamos abaixo assertivas relacionadas aos critérios\\npara o registro contábil dos títulos e valores mobiliários adquiridos por instituições\\nfinanceiras e demais instituições autorizadas a funcionar pelo Banco Central do Brasil, exceto\\ncooperativas de crédito, agências de fomento e sociedades de crédito ao\\nmicroempreendedor.\\n\\nAssinale a opção que contém a afirmativa incorreta.\",\"c\":\"Vamos analisar todas as alternativas e encontrar a incorreta.\\n\\nItem correto. Conforme vimos, os TVMs adquiridos devem ser classificados em uma das três categorias: I-negociação, II-disponível para venda, III-mantidos até o vencimento. (art. 1º, da Circular 3.068 e item 1.4.1.1 do Cosif).\\n\\nItem correto. É literalidade do art. 1º, § 1º, da Circular 3.068 e item 1.4.1.2 do Cosif.\\n\\nItem errado! A valorização ou a desvalorização decorrente do ajuste da marcação a mercado dos títulos classificados na categoria títulos para negociação deve ser efetuada em contrapartida à adequada conta de receitas (quando o título valorizar) ou de despesas (quando o título desvalorizar), e não conta de rendas/despesas a apropriar. (art. 2º, inciso I, da Circular 3.068 e item 1.4.1.7 do Cosif).\\n\\nItem correto. O ajuste da marcação a mercado da categoria disponível para venda deve ser contabilizada em conta destacada do PL para esse fim. (art. 2º, inciso II, da Circular 3.068 e item 1.4.1.7 do Cosif).\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 29 Carlos Roberto Correa Aula 01 (Somente em PDF)\\n\\nItem correto. Os títulos classificados nas categorias I e II devem ser marcados a mercado no mínimo por ocasião dos balancetes e balanços. (art. 2º da Circular 3.068 e item 1.4.1.7 do Cosif).\",\"o\":[\"Devem ser classificados nas categorias: títulos para negociação, títulos disponíveis para venda, e títulos mantidos até o vencimento.\",\"Na categoria títulos para negociação, devem ser registrados aqueles adquiridos com o propósito de serem ativa e frequentemente negociados.\",\"A valorização ou a desvalorização decorrente do ajuste ao valor de mercado dos títulos classificados na categoria \\\"títulos para negociação\\\" deve ser efetuada em contrapartida à adequada conta de rendas/despesas a apropriar.\",\"A valorização ou a desvalorização decorrente do ajuste ao valor de mercado dos títulos classificados na categoria \\\"títulos disponíveis para venda\\\" deve ser efetuada em contrapartida à conta destacada do patrimônio líquido.\",\"Os títulos e valores mobiliários classificados nas categorias \\\"títulos para negociação\\\" e \\\"títulos disponíveis para venda\\\", devem ser ajustados pelo valor de mercado, no mínimo por ocasião dos balancetes e balanços.\"],\"g\":2},{\"_id\":1,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"CESGRANRIO Analista do Bacen · 2009\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Analise as proposições a seguir a respeito de\\noperações financeiras.\\n\\n....\\n\\nIV – Os títulos e os valores mobiliários adquiridos por uma instituição financeira devem ser\\nregistrados pelo valor efetivamente pago, inclusive corretagens e emolumentos, e devem ser\\nclassificados nas seguintes categorias: títulos para negociação, títulos disponíveis para venda\\ne títulos mantidos até o vencimento.\",\"c\":\"Item correto, de acordo com o art. 1º da Circular 3.068 e com o item 1.4.1.1.do Cosif.\",\"g\":\"C\"},{\"_id\":2,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação a procedimentos contábeis aplicáveis a\\noperações com títulos de renda fixa realizadas por instituições financeiras, julgue o item a seguir:\\nAs rendas dos títulos, inclusive cotas de fundos de renda fixa, são creditadas na própria conta que\\nregistra os títulos, a débito de rendas de títulos de renda fixa.\",\"c\":\"Conforme vocês puderam observar nos vários exemplos anteriores de contabilização dos títulos, as rendas dos títulos são debitadas (lançamento a débito) na própria conta que registra os títulos e creditadas (lançamento a crédito) na conta de rendas de títulos de renda fixa.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 54 Carlos Roberto Correa Aula 01 (Somente em PDF)\\n\\nExemplo:\\n\\nLançamento a débito na conta que registra o título Natureza Código/Conta Título Contábil Valor D 1.3.1.10.07 – 3 TVM/LIVRES/TRF/NTN 105,20 C 7.1.5.10.00 – 0 Rendas de Títulos de Renda Fixa 105,20\\n\\nLançamento a crédito na conta Rendas de títulos de renda fixa\\n\\nPortanto, a questão está errada.\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"CESGRANRIO Analista Bacen · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Ao final do mês em curso, a Contabilidade do Banco ABC\\nprecisa apropriar os rendimentos de suas operações com títulos de renda fixa, no valor de R$\\n200.000,00.\\n\\nO registro contábil, em reais, será:\",\"c\":\"Como vocês observaram nos vários exemplos de contabilização de títulos desta aula, os rendimentos dos títulos (valores a apropriar dos juros da curva do papel) são contabilizados a débito da conta que registra o título e a crédito da conta de renda de títulos, conforme exemplo abaixo:\\n\\nAjuste TVM\\n\\nRendimentos de Títulos de Renda Fixa 40 + 30 = 70 Natureza Código/Conta Título Contábil Valor D 1.3.1.10.05 - 9 TVM/LIVRES/TRF/LTN 70,00 C 7.1.5.10.00 - 0 Rendas de Títulos de Renda Fixa 40,00 TVM-Ajuste Positivo Valor de C 7.1.5.90.10 - 9 30,00 Mercado/Negociação A única alternativa que lança a débito na conta de títulos e a crédito na conta de rendas com títulos é a alternativa C.\",\"o\":[\"D Disponibilidades 200.000 C Lucros com títulos de renda fixa 200.000\",\"D Disponibilidades 200.000 C Lucros com intermediação financeira 200.000\",\"D Títulos de renda fixa 200.000 C Rendas com títulos de renda fixa 200.000\",\"D Títulos de renda fixa 200.000 C Lucros com intermediação financeira 200.000 BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 55 Carlos Roberto Correa Aula 01 (Somente em PDF)\",\"D Rendas com títulos de renda fixa 200.000 C Disponibilidades 200.000\"],\"g\":2},{\"_id\":4,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação a procedimentos contábeis aplicáveis a operações\\ncom títulos de renda fixa realizadas por instituições financeiras, julgue o item a seguir.\\n\\nAs rendas dos títulos de renda fixa devem ser reconhecidas até a data da venda definitiva, sendo\\nque o lucro ou prejuízo será a diferença entre o preço de venda e o valor atualizado até a data da\\noperação.\",\"c\":\"Questão correta. Temos aqui a transcrição literal do Cosif 1.4.3.2.g. As rendas dos títulos de renda fixa devem ser reconhecidas até a data da venda definitiva, sendo que o lucro ou prejuízo será a diferença entre o preço de venda e o valor atualizado até a data da operação.\",\"g\":\"C\"},{\"_id\":5,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item que se segue acerca das operações financeiras de\\ninstituições financeiras.\\n\\nRelativamente a títulos de renda fixa, carteira própria bancada de instituição financeira é\\nrepresentada pelos títulos que permanecem em estoque, livres para negociação, oriundos de\\ncompras definitivas ou recompras, registrados na conta de títulos de renda fixa.\",\"c\":\"Questão correta, de acordo com o item 1.4.3.1 do Cosif.\",\"g\":\"C\"},{\"_id\":6,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação a procedimentos contábeis aplicáveis a operações\\ncom títulos de renda fixa realizadas por instituições financeiras, julgue o item a seguir.\\n\\nOs rendimentos atribuídos aos títulos contabilizam-se mensalmente, ou em períodos menores,\\npelo método exponencial ou linear, de acordo com a cláusula de remuneração do título, com base\\nna taxa de aquisição, de tal maneira que, na data correspondente ao dia do vencimento, os seus\\nvalores estejam atualizados em razão da fluência de seus prazos.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 73\\nCarlos Roberto Correa\\nAula 01 (Somente em PDF)\",\"c\":\"Questão correta, de acordo com o Item 1.4.3.2.c do Cosif. Percebam que os examinadores cobram muitas vezes a literalidade do Cosif, por isso é importante que vocês se acostumem a “letra fria” da norma.\",\"g\":\"C\"},{\"_id\":7,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No contexto da avaliação patrimonial de títulos de renda\\nvariável - como as ações subscrita, ou havidas por investimentos compulsórios, destinadas à\\nnegociação em mercado, bônus de subscrição de companhias abertas, certificados e cotas de\\nfundos de renda variável, ações adquiridas no mercado para livre negociação e outros títulos\\nadquiridos ou subscritos - das instituições financeiras e demais entidades autorizadas a funcionar\\npelo BACEN, exceto fundos de investimento, julgue o item abaixo:\\n\\nOs títulos de renda variável adquiridos para a formação de carteira própria devem ser registrados\\napenas pelo valor efetivamente pago, excluindo corretagens e emolumentos.\",\"c\":\"Questão incorreta. Os títulos de renda variável adquiridos para a formação de carteira própria devem ser registrados pelo valor efetivamente pago, INCLUINDO corretagens e emolumentos.\",\"g\":\"E\"},{\"_id\":8,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação a procedimentos contábeis aplicáveis a\\noperações com títulos de renda fixa realizadas por instituições financeiras, julgue o item a seguir:\\nOs prêmios de continuidade recebidos em dinheiro, nos casos de repactuação dos prazos de\\nvencimento de debêntures pertencentes à sociedade, contabilizam-se a crédito da adequada conta\\nde rendas de títulos de renda fixa, na data da repactuação.\",\"c\":\"Questão incorreta. De acordo com o Cosif 1.4.3.2.e, os prêmios de continuidade recebidos em dinheiro, nos casos de repactuação dos prazos de vencimento de debêntures pertencentes à sociedade, contabilizam-se a crédito da adequada conta de rendas a apropriar, para a apropriação mensal ou em períodos menores, em razão da fluência de seu prazo, a crédito de RENDAS DE TÍTULOS DE RENDA FIXA.\",\"g\":\"E\"},{\"_id\":9,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No contexto da avaliação patrimonial de títulos de renda\\nvariável - como as ações subscrita, ou havidas por investimentos compulsórios, destinadas à\\nnegociação em mercado, bônus de subscrição de companhias abertas, certificados e cotas de\\nfundos de renda variável, ações adquiridas no mercado para livre negociação e outros títulos\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 74\\nCarlos Roberto Correa\\nAula 01 (Somente em PDF)\\n\\nadquiridos ou subscritos - das instituições financeiras e demais entidades autorizadas a funcionar\\npelo BACEN, exceto fundos de investimento, julgue o item abaixo:\\n\\nAs entidades tomadoras de ações por empréstimo devem registrar as ações recebidas por\\nempréstimo apenas em contas de compensação.\",\"c\":\"Questão incorreta. As ações recebidas por empréstimo devem ser registradas no ativo no título TÍTULOS DE RENDA VARIÁVEL (1.3.1.20.00-1), em contrapartida a lançamento no passivo no título contábil CREDORES POR EMPRÉSTIMOS DE AÇÕES (4.9.5.88.00-2).\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 02":{"questoesPdf":[{"title":"Questões Extraídas — Instrumentos Financeiros Derivativos · Aula 02 (9 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF · Aula 02 · Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 02 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 02 — <b>Instrumentos Financeiros Derivativos</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 02 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Acerca dos conceitos relativos a operações com derivativos,\\njulgue os itens a seguir.\\n\\nI- Derivativos são instrumentos financeiros cujo valor depende (ou deriva) do preço ou do\\ndesempenho de mercado de um bem básico, de uma taxa de referência ou de um índice.\",\"c\":\"BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 12 Carlos Roberto Correa\\n\\nCorreta a afirmação, de acordo com art. 1º, Inciso V, Parágrafo 1º, da Circular 3.082/2002, e com o item 1.4.4.2 do COSIF.\",\"g\":\"C\"},{\"_id\":1,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item abaixo, acerca de derivativos.\\n\\nI- Especulador é a pessoa física ou jurídica que busca tirar proveito da variação na\\ndiferença entre o preço de dois ativos ou mercados ou das expectativas futuras de\\nmudança nessa diferença, aproveitando uma distorção momentânea de preços.\",\"c\":\"ativos ou mercados ou das expectativas futuras de mudança nessa diferença, aproveitando uma distorção momentânea de preços, é o ARBITRADOR.\",\"g\":\"E\"},{\"_id\":2,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue os itens a seguir, de acordo com o Plano Contábil das\\nInstituições do Sistema Financeiro Nacional (COSIF).\\n\\nNas operações com opções realizadas por conta própria pelas instituições financeiras, pelas demais\\ninstituições autorizadas a funcionar pelo BACEN e pelas administradoras de consórcios, deve-se\\nregistrar, na data da operação, o valor dos prêmios pagos ou recebidos na adequada conta de ativo\\nou passivo, respectivamente. Se a opção for exercida, deve ser baixado como receita ou despesa,\\nconforme o caso.\",\"c\":\"prêmios pagos ou recebidos na adequada conta de ativo ou passivo, respectivamente, nela permanecendo até o o efetivo exercício da opção, se for o caso, quando então deve ser baixado como redução ou aumento do custo do bem ou direito, pelo efetivo exercício, ou como receita ou despesa, no caso de NÃO exercício.\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista do Bacen · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"De acordo com a circular nº 3.082 do Bacen, artigo 3°, as\\noperações com instrumentos financeiros derivativos destinadas a hedge devem ser\\nclassificadas somente nas categorias hedge de risco.\\n\\nDe mercado e hedge de risco de crédito.\\n\\nSistêmico e hedge de fluxo de caixa.\\n\\nDe mercado e hedge de fluxo de resultado.\\n\\nDe crédito e hedge de risco de liquidez.\\n\\nDe mercado e de hedge de fluxo de caixa.\",\"c\":\"Como vimos, devem ser classificadas como hedge de mercado e de fluxo de caixa. Item 1.4.4.10 do COSIF.\",\"o\":[],\"g\":4},{\"_id\":4,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista do Bacen · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Relativamente às operações com instrumentos\\nfinanceiros derivativos destinadas a hedge, o COSIF estabelece os seguintes procedimentos,\\nexceto:\\n\\nNa categoria hedge de fluxo de caixa, devem ser classificados os instrumentos financeiros\\nderivativos que se destinem a compensar variação no fluxo de caixa futuro estimado da\\ninstituição.\\n\\nEntende-se por hedge a designação de um ou mais instrumentos financeiros derivativos com\\no objetivo de compensar, no todo ou em parte, os riscos decorrentes da exposição às\\nvariações no valor de mercado ou no fluxo de caixa de qualquer ativo, passivo, compromisso\\nou transação futura prevista, registrado contabilmente ou não, ou ainda grupos ou partes\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 57\\nCarlos Roberto Correa\\n\\ndesses itens com características similares e cuja resposta ao risco objeto de hedge ocorra de\\nmodo semelhante.\\n\\nNa categoria hedge de risco de mercado devem ser classificados os instrumentos financeiros\\nderivativos que se destinem a compensar riscos decorrentes da exposição à variação no valor\\nde mercado do item objeto de hedge.\\n\\nDevem ser classificadas em uma das categorias a seguir: hedge de risco de mercado, hedge\\nde fluxo de caixa e hedge de risco cambial.\\n\\nOs títulos e valores mobiliários classificados na categoria mantidos até o vencimento, podem\\nser objeto de hedge, observando que na avaliação do instrumento financeiro derivativo\\ncorrespondente deverá ser desconsiderada a valorização ou desvalorização decorrente de\\najustes a valor a mercado.\",\"c\":\"Vamos a cada item:\\n\\nO item “a” está correto, de acordo com o item 1.4.4.13 do COSIF.\\n\\nO item “b” está correto, de acordo com o item 1.4.4.11 do COSIF.\\n\\nO item “c” está correto, de acordo com o item 1.4.4.12 do COSIF.\\n\\nO item “d” esta incorreto. O COSIF não dispõe sobre “hedge cambial”, de acordo com o item 1.4.4.10 do COSIF.\\n\\nO item “e” está correto, de acordo com o item 1.4.4.14 do COSIF.\",\"o\":[],\"g\":3},{\"_id\":5,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista do Bacen · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Os instrumentos de derivativos devem ser classificados\\nna categoria de hedge de risco de mercado quando a razão desta operação for apenas de:\\n\\nMaximizar os ganhos com a especulação financeira.\\n\\nMinimizar as perdas em relação às variações do valor de mercado do item objeto de hedge.\\nMaximizar os ganhos em relação às variações do valor de mercado do item objeto de hedge\\nCompensar total ou parcialmente as variações do valor de mercado do item objeto de hedge.\\nDiversificar a carteira do banco e com isso minimizar o risco esperado.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 58\\nCarlos Roberto Correa\",\"c\":\"no todo ou em parte, os riscos decorrentes da exposição às variações no valor de mercado (exposição a variações nas taxas de juros, câmbio, preço de mercadorias ou de ações).\\n\\nVamos analisar cada alternativa:\\n\\nO hedge de risco de mercado é para proteção e não especulação;\\n\\nA definição é compensar no todo ou em parte a exposição aos riscos de mercado, e não “somente” minimizar as perdas em relação às variações do valor de mercado;\\n\\nO hedge é para proteção, e não para maximizar ganhos;\\n\\nAlternatica correta: compensar total ou parcialmente as variações do valor de mercado do item objeto de hedge, de acordo com o item 1.4.4.12;\\n\\nO objetivo do hedge é proteção da carteira, e não diversificação.\",\"o\":[],\"g\":3},{\"_id\":6,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista do Bacen · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A propósito dos procedimentos para o registro contábil\\ndas operações com instrumentos financeiros derivativos realizadas por conta própria pelas\\ninstituições financeiras, demais instituições autorizadas a funcionar pelo Banco Central do\\nBrasil e administradoras de consórcios, abaixo são apresentadas assertivas, sendo uma delas\\nincorreta. Assinale a opção que contém a afirmativa errada.\\n\\nNas operações a termo deve ser registrado, na data da operação, o valor final contratado\\ndeduzido da diferença entre esse valor e o preço à vista do bem ou direito em subtítulo\\nretificador de uso interno da adequada conta de ativo ou passivo, reconhecendo as receitas e\\ndespesas, em razão do prazo de fluência dos contratos, no mínimo, por ocasião dos\\nbalancetes mensais e balanços.\\n\\nNas operações com opções deve ser registrado, na data da operação, o valor dos prêmios\\npagos ou recebidos na adequada conta de ativo ou passivo, respectivamente, nela\\npermanecendo até o efetivo exercício da opção, se for o caso, quando então deve ser baixado\\ncomo redução ou aumento do custo do bem ou direito, pelo efetivo exercício, ou como\\nreceita ou despesa, no caso de não exercício, conforme o caso.\\n\\nAs operações com instrumentos financeiros derivativos devem ser avaliadas pelo valor de\\nmercado, no mínimo, por ocasião dos balancetes mensais e balanços, computando-se a\\nvalorização ou a desvalorização em contrapartida a conta destacada no patrimônio líquido,\\nsendo a receita ou despesa registrada somente no resultado do período em que o contrato\\nfor liquidado.\\n\\nNas operações com outros instrumentos financeiros derivativos, devem ser realizados\\nregistros em contas de ativo ou passivo de acordo com as características do contrato,\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 59\\nCarlos Roberto Correa\\n\\ninclusive aqueles embutidos, que devem ser registrados separadamente em relação ao\\ncontrato a que estejam vinculados.\\n\\nNas relações de futuro deve ser registrado o valor dos ajustes diários na adequada conta de\\nativo ou passivo, devendo ser apropriados como receita ou despesa, no mínimo, por ocasião\\ndos balancetes mensais e balanços.\",\"c\":\"Vamos comentar cada item:\\n\\nItem “correto”, de acordo com o item 1.4.4.1-a do COSIF Item “correto”, de acordo com o item 1.4.4.1-b do COSIF Item “incorreto”. As operações com instrumentos financeiros derivativos devem ser avaliadas pelo valor de mercado, no mínimo, por ocasião dos balancetes mensais e balanços, computando- se a valorização ou a desvalorização em contrapartida à adequada conta de receita ou despesa, no resultado do período. De acordo com o item 1.4.4.7 do COSIF.\\n\\nCorreto, de acordo com o item 1.4.4.1 e do COSIF Correto, de acordo com o item 1.4.4.1 c do COSIF\",\"o\":[],\"g\":2},{\"_id\":7,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Bancário NOSSA CAIXA DESENVOLVIMENTO · 2011\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os valores a receber relativos\\na rendas auferidas decorrentes de operações de swap, avaliados pelo valor de mercado, NÃO\\npodem ser registrados em:\\n\\nDiferencial a Receber-Hedge de título mantido até o vencimento.\\n\\nDiferencial a Receber- Operações com garantia de Bolsa.\\n\\nDiferencial a Receber- Operações com garantia de Bolsa- Hedge de título mantido até o\\nvencimento.\\n\\nTítulos de renda fixa vinculados a recompras.\\n\\nDiferencial a Receber.\",\"c\":\"Conforme vimos nesta aula, os valores a receber relativos a rendas auferidas decorrentes de operações de swap são “diferencial a receber”. A alternativa D está incorreta (não tem nada a ver com diferencial a receber ou a pagar).\",\"g\":\"E\"},{\"_id\":8,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação a procedimentos contábeis aplicáveis a\\noperações dos mercados a termo, futuro e de opções realizadas por instituições financeiras,\\njulgue o seguinte item.\\n\\nOs valores dos contratos de operações de compra e venda de ações, outros ativos financeiros\\ne mercadorias, realizadas por conta própria, nos mercados futuro e de opções, devem ser\\nregistrados apenas nas adequadas contas patrimoniais, quando couber, não devendo haver\\nescrituração em contas de compensação.\",\"c\":\"Item errado! Vimos que o valor dos contratos de opções, tanto de compra como de venda, devem ser lançados em conta de compensação, de acordo com o item 1.4.4.3 do COSIF.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 03":{"questoesPdf":[{"title":"Questões Extraídas — Operações de Crédito · Aula 03 (10 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF · Aula 03 · Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 03 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 03 — <b>Operações de Crédito</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 03 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista do Bacen · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No momento em que um banco concede empréstimo a\\num cliente, os grupos de contas dos seus demonstrativos financeiros terão os seguintes\\nimpactos:\",\"c\":\"Na concessão do crédito da operação de empréstimo, lançamos a operação a débito no ativo, na conta que registra os Empréstimos, o que aumenta o seu valor e, consequentemente, aumenta o Ativo.\\n\\nD – 1.6.1.20.00-8 – Empréstimos\\n\\nEm contrapartida, lançamos a crédito o valor da operação de crédito na conta corrente do cliente, em sua conta de depósito à vista, o que aumenta a “conta de depósitos à vista” no passivo do banco (captação) e, consequentemente, aumenta também o passivo do banco.\\n\\nC – 4.1.1.20.00-4 – Depósito de Pessoa Jurídica\\n\\nPortanto, a operação de empréstimo provoca o aumento do Ativo e aumento do Passivo.\",\"o\":[\"diminuição do Passivo e diminuição do Ativo.\",\"aumento do Ativo e aumento do Patrimônio Líquido (via resultado).\",\"aumento do Ativo e aumento do Passivo.\",\"aumento da Receita e diminuição de Despesas, porém o resultado é positivo.\",\"diminuição do Passivo e aumento do Patrimônio Líquido.\"],\"g\":2},{\"_id\":1,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista do Bacen · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Apresentamos abaixo frases relacionadas aos conceitos\\ne características das operações de crédito, conforme disposto no COSIF.\\n\\nAssinale o acerto das afirmações adiante e marque com V as verdadeiras e com F as falsas,\\nem seguida, marque a opção correta.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 19\\nCarlos Roberto Correa\\n\\n( ) Na classificação dessas operações, pelos diversos títulos contábeis, deve-se ter em conta a\\naplicação dada aos recursos, por tipo ou modalidade de operação, e a atividade\\npredominante do tomador do crédito.\\n\\n( ) As operações de crédito são classificadas nas seguintes modalidades: empréstimos, títulos\\ndescontados e financiamentos.\\n\\n( ) Empréstimos são as operações realizadas com destinação específica ou vínculo à\\ncomprovação da aplicação dos recursos.\",\"c\":\"Vamos analisar cada alternativa relativas às operações de crédito:\\n\\n(V) Na classificação das operações de crédito nas diversas contas do COSIF, devemos levar em conta a aplicação dada aos recursos por tipo ou modalidade de operação, e a atividade predominante do tomador do crédito.\\n\\n(V) Como vimos, no COSIF as operações de crédito são classificadas em: empréstimos, títulos descontados e financiamentos.\\n\\n(F) Empréstimos são as operações realizadas com sem destinação específica ou e sem vínculo à comprovação da aplicação dos recursos.\\n\\nPortanto, V, V e F.\",\"o\":[\"V, V, V\",\"F, F, V\",\"V, F, F\",\"F, V, V\",\"V, V, F\"],\"g\":4},{\"_id\":2,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"VUNESP BNDES Contador · 2001\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O Banco RKW descontou duplicatas da Cia. Gaúcha,\\ncom prazo de 60 dias no valor nominal de R$ 30.000,00, utilizando uma taxa de desconto\\nsimples de 5% ao mês (comercial). Cobrou, adicionalmente, despesas bancárias no valor de\\nR$ 500,00. Sabendo-se que o banco contabiliza o valor dos títulos no seu ativo pelo valor\\ndescontado e apropria a receita de descontos conforme o prazo transcorrido, o lançamento\\nque registrará a operação na escrituração do banco, na data do desconto, será:\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 22\\nCarlos Roberto Correa\",\"c\":\"Vamos começar recordando como desenhar uma operação de desconto:\\n\\n( N )\\n\\nValor Nominal ( A )\\n\\nDesconto Valor Atual N A 100 100 – i x n ( D )\\n\\nn 0 D i x n (Tempo)\\n\\nA partir do desenho temos três equações.\\n\\nA D N = = 100 − i x n i x n 100 N= R$ 30.000,00 i= 5% a.m.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 23 Carlos Roberto Correa\\n\\nA=?\\n\\nn = 2 meses\\n\\nSubstituindo os dados na equação teremos:\\n\\nA N = 100% − i x n 100%\\n\\nA 30.000 = 100% − 5% x 2 1\\n\\nA 30.000 = 100% − 10% 1\\n\\nA x 1 = 30.000 x (100% − 10%) ⟶ A = 30.000 x (90%)\\n\\n𝐀 = 𝟐𝟕. 𝟎𝟎𝟎, 𝟎𝟎 O valor total das duplicatas daqui a 60 dias (N) será de R$ 30.000,00. Descontando as referidas duplicatas, e as trazendo a valor presente (A), com taxa de desconto simples de 5% ao mês, teremos 10% para 2 meses.\\n\\nAdemais, o banco cobra uma taxa de R$ 500,00.\\n\\nLogo, o cliente receberá:\\n\\n𝐕𝐚𝐥𝐨𝐫 𝐫𝐞𝐜𝐞𝐛𝐢𝐝𝐨 𝐩𝐞𝐥𝐨 𝐜𝐥𝐢𝐞𝐧𝐭𝐞 = (Valor Descontado) − (Tarifas)\\n\\n𝐕𝐚𝐥𝐨𝐫 𝐫𝐞𝐜𝐞𝐛𝐢𝐝𝐨 𝐩𝐞𝐥𝐨 𝐜𝐥𝐢𝐞𝐧𝐭𝐞 = (27.000,00) − (500,00) = 𝐑$ 𝟐𝟔. 𝟓𝟎𝟎, 𝟎𝟎 Dessarte, os lançamentos do banco serão:\\n\\nNatureza Título Contábil Valor (R$)\\n\\nD - Títulos Descontados 27.000,00 C - Receita de Serviços 500,00 C - Depósitos de PJ 26.500,00 O banco apropriará, mensalmente os rendimentos como receita, de sorte que, no vencimento, ele terá o seu valor nominal.\",\"o\":[\"Bancos = 27.000,00 Duplicatadas Descontadas = 27.000,00\",\"Títulos Descontados = 27.000,00 Receita de Serviços = 500,00 Depósitos = 26.500,00\",\"Duplicatas a Receber 27.000,00 Duplicatadas Descontadas 27.000,00\",\"Títulos Descontados = 30.000,00 Receitas de Serviços = 3.500,00 Depósitos = 26.500,00\",\"Títulos Descontados = 30.000,00 Despesas de Serviços = 3.000,00 Depósitos = 27.000,00\"],\"g\":1},{\"_id\":3,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"FCC Analista do Bacen · 2006\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No momento em que um banco rebaixa a classificação\\nde crédito de um empréstimo concedido de B para C (dentro da escala do Banco Central de\\nAA - H), os grupos contábeis dos seus demonstrativos financeiros terão os seguintes\\nimpactos:\",\"c\":\"Vamos pensar juntos: se a classificação de crédito foi do nível de risco B para o nível de risco C, teremos um aumento na provisão.\\n\\nA provisão será lançada a crédito no ativo, reduzindo-o. Assim, consequentemente o ativo diminuirá.\\n\\nA contrapartida para o lançamento da provisão é um lançamento a débito de despesa nas contas de resultado.\\n\\nA despesa reduzirá o Patrimônio Líquido (PL) via resultado.\\n\\nDeste modo, teremos diminuição do Ativo e diminuição do Patrimônio Líquido (via resultado).\",\"o\":[\"diminuição da Receita e aumento de Despesas, porém o resultado é negativo.\",\"aumento do Passivo e diminuição do Ativo.\",\"diminuição do Ativo e diminuição do Patrimônio Líquido (via resultado).\",\"aumento do Passivo e diminuição do Patrimônio Líquido (via resultado). BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 44 Carlos Roberto Correa\",\"diminuição do Ativo e aumento do Passivo.\"],\"g\":2},{\"_id\":4,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista do Bacen · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"(e mais 2 concursos) - Abaixo são apresentadas três\\nassertivas relacionadas ao registro contábil das operações de cessão de direitos creditórios de\\noperações de crédito.\\n\\nAvalie o acerto das afirmações e marque com V as verdadeiras e com F as falsas, em seguida,\\nmarque a opção correta.\\n\\n( ) As operações de crédito objeto de cessão dos respectivos direitos, com ou sem\\ncoobrigação, devem ser registradas na cessionária conforme a modalidade da operação\\noriginal, observada a atividade predominante do tomador do crédito.\\n\\n( ) O resultado da cessão de operações de crédito deve ser apurado pela instituição cedente\\nem razão do prazo contratual, segundo o regime de competência.\\n\\n( ) No caso de a instituição cedente vir a assumir os pagamentos relativos às operações\\ncedidas com coobrigação, por inadimplemento do tomador do crédito ou arrendatário, o\\ncrédito decorrente deve ser classificado no título contábil utilizado para registro da operação\\noriginal, observada a situação do crédito.\",\"c\":\"O primeiro enunciado está perfeito, Verdadeiro.\\n\\nO segundo enunciado está errado:\\n\\n“O resultado da cessão de operações de crédito deve ser apurado pela instituição cedente em razão do prazo contratual, segundo o regime de competência”.\\n\\nNa verdade o resultado da cessão da operação de crédito deve ser apurado pela instituição cedente, na data da contratação da operação, mediante baixa na conta do Cosif que registrava a operação de crédito.\\n\\nO terceiro enunciado está perfeito também, Verdadeiro.\\n\\nPortanto, V, F, V.\",\"o\":[\"V, F, V\",\"V, F, F\",\"V, V, F\",\"F, F, F\",\"F, V, F BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 45 Carlos Roberto Correa\"],\"g\":0},{\"_id\":5,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista do Bacen · 2002\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A propósito da classificação das operações de crédito\\npor nível de risco pelas instituições financeiras e demais instituições autorizadas a funcionar\\npelo Banco Central do Brasil, apresentamos a seguir cinco assertivas.\\n\\nAssinale a opção que contém a afirmativa errada.\",\"c\":\"Vamos analisar cada item:\\n\\na) A classificação da operação no nível de risco correspondente é de responsabilidade do Banco\\n\\nCentral do Brasil.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 46 Carlos Roberto Correa\\n\\nNão! A classificação da operação no nível de risco correspondente é de responsabilidade da instituição financeira.\\n\\nOs itens “b”, “c”, “d” e ”e” estão corretos!\",\"o\":[\"A classificação da operação no nível de risco correspondente é de responsabilidade do Banco Central do Brasil.\",\"A classificação da operação no nível de risco correspondente deve ser efetuada com base em critérios consistentes e verificáveis, amparada por informações internas e externas.\",\"As operações de crédito devem ser classificadas, em ordem crescente de risco, nos seguintes níveis: nível AA; nível A; nível B; nível C; nível D; nível E; nível F; nível G e nível H.\",\"A provisão para fazer face aos créditos de liquidação duvidosa deve ser constituída mensalmente, não podendo ser inferior ao somatório decorrente da aplicação dos percentuais estabelecidos na regulamentação em vigor, sem prejuízo da responsabilidade dos administradores das instituições pela constituição de provisão em montantes suficientes para fazer face a perdas prováveis na realização dos créditos.\",\"O Banco Central do Brasil pode determinar alteração dos critérios de classificação de créditos, de contabilização e de constituição de provisão.\"],\"g\":0},{\"_id\":6,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"CESGRANRIO Analista do Bacen · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No encerramento do último semestre,\\ndeterminado banco tinha a seguinte carteira de operações de crédito, em reais:\\n\\nDevem ser considerados, também, os níveis de risco determinados pelo Banco Central e os\\nrespectivos percentuais para cálculo da provisão para créditos de liquidação duvidosa.\\n\\nA partir dessas informações, qual a provisão para créditos de liquidação duvidosa e a\\nrespectiva contabilização?\",\"c\":\"Vamos lá, pessoal.\\n\\nNível de Risco Atraso Saldo Vencido Provisão % Provisão (R$)\\n\\nAA - - - - A - - 0,5% - B Entre 15 e 30 dias 60.000,00 1% 600,00 C Entre 31 e 60 dias 40.000,00 3% 1.200,00 D Entre 61 e 90 dias 20.000,00 10% 2.000,00 E Entre 91 e 120 dias 15.000,00 30% 4.500,00 F Entre 121 e 150 dias 10.000,00 50% 5.000,00 G Entre 151 e 180 dias 7.000,00 70% 4.900,00 H Superior a 180 dias 4.000,00 100% 4.000,00 Total 156.000,00 22.200,00 A provisão foi de R$ 22.200,00. A CESGRANRIO considerou provisão de 0,5% sobre o saldo vencido de 5 dias de R$ 80 mil. Entretanto, a normatização do BACEN dispõe os atrasos a partir de 15 dias.\\n\\nEmbora um banco, de forma conservadora, possa estabelecer provisão para atrasos a partir de 5 dias, esse critério não está disposto na normatização do BACEN (Resolução 2.682/1999). O banco está sendo mais conservador do que a norma exige. Nesse caso, não teria óbice do BACEN.\\n\\nEntretanto, a questão não deixou isso claro. Assim, marcamos a letra C do gabarito, mas essa questão foi plenamente suscetível à anulação.\",\"o\":[\"D - Despesas financeiras 18.600.000 C - Provisões para operações de crédito 18.600.000\",\"D - Despesas financeiras 16.600.000 C - Provisões para operações de crédito 16.600.000\",\"D - Despesas de provisões operacionais 22.600.000 C - Provisões para operações de crédito 22.600.000 BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 47 Carlos Roberto Correa\",\"D - Despesas de provisões operacionais 18.600.000 C - Operações de crédito 18.600.000\",\"D - Despesas de provisões operacionais 16.600.000 C - Operações de crédito 16.600.000\"],\"g\":2},{\"_id\":7,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"CESGRANRIO Analista do Bacen · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Um banco recuperou, por meio de\\nrenegociação, R$ 12.000.000,00 de créditos já baixados como prejuízos, que serão recebidos\\nem 3 meses.\\n\\nQual a contabilização recomendada, em reais?\",\"c\":\"Os créditos baixados como prejuízo e porventura renegociados devem ser registrados pelo exato valor da renegociação, observado que o registro do ganho eventualmente auferido deve ser contabilizado a débito da conta do ativo que registra a operação de crédito (Operações de crédito - Ativo circulante) e a crédito da conta RECUPERAÇÃO DE CRÉDITOS BAIXADOS COMO PREJUÍZO. Ademais, deve ser feita a baixa simultânea dos seus valores das respectivas contas de compensação, mas a questão não entrou nesse mérito.\\n\\nPortanto:\\n\\nD - Operações de crédito - Ativo circulante 12.000.000 C - Recuperação de créditos baixados como prejuízos - DRE 12.000.000\",\"o\":[\"D - Operações de crédito - Ativo circulante 12.000.000 C - Recuperação de créditos baixados como prejuízos - DRE 12.000.000\",\"D - Operações de crédito - Ativo circulante 12.000.000 C - Rendas de operações de créditos 12.000.000\",\"D - Disponibilidades 12.000.000 C - Rendas de operações de créditos 12.000.000\",\"D - Disponibilidades 12.000.000 C - Provisão para créditos de liquidação duvidosa 12.000.000\",\"D - Provisão para créditos de liquidação duvidosa 12.000.000 C - Recuperação de créditos baixados como prejuízos - DRE 12.000.000\"],\"g\":0},{\"_id\":8,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item a seguir, de acordo com o Plano\\nContábil das Instituições do Sistema Financeiro Nacional (COSIF).\\n\\nConsidere que a carteira de operações de crédito de uma instituição financeira inclua, no\\nmomento do levantamento do balancete mensal, as operações descritas na tabela abaixo.\\nCom base nessas informações, é correto afirmar que a provisão para créditos de liquidação\\nduvidosa constituída para essas operações corresponde a R$ 36.000,00.\\n\\nCliente Montante (em R$) Atraso (em dias)\\n\\nAlfa 80.000 20\\nBeta 90.000 40\\nDelta 120.000 65\\nGama 75.000 120\\n( ) Certo\\n( ) Errado\",\"c\":\"Vamos lá, pessoal! Matemática básica.\\n\\nCliente Montante (em Atraso (em Provisão Provisão R$) dias) % R$ Alfa 80.000,00 20 1% 800,00 Beta 90.000,00 40 3% 2.700,00 Delta 120.000,00 65 10% 12.000,00 Gama 75.000,00 120 30% 22.500,00 Total 38.000,00 Assim, a provisão será de R$ 38 mil e não de R$ 36 mil como afirma a questão.\",\"g\":\"E\"},{\"_id\":9,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista do Bacen · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Ainda no que se refere ao COSIF, julgue o item.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF 50\\nCarlos Roberto Correa\\n\\nEm uma operação de desconto de títulos, na qual o cliente recebe o valor líquido das\\ndespesas de juros, a instituição financeira deverá registrar o valor correspondente aos juros\\nem conta patrimonial de rendas antecipadas.\\n\\n( ) Certo\\n( ) Errado\",\"c\":\"Negativo. Para a IF os juros devem ser apropriados como receita de acordo com o regime de competência.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 04":{"questoesPdf":[{"title":"Questões Extraídas — Ativos e Provisões · Aula 04 (6 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF · Aula 04 · Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 04 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 04 — <b>Ativos e Provisões</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 04 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"CESGRANRIO Petrobrás Contador Júnior · 2011\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"A diferença entre arrendamento mercantil\\nfinanceiro e operacional é que, enquanto o arrendamento mercantil financeiro transfere de forma\\nsubstancial os riscos e benefícios inerentes à propriedade, o arrendamento mercantil operacional:\",\"c\":\"como financeiro se ele transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade. Um arrendamento mercantil deve ser classificado como operacional se ele não transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade.\\n\\nPortanto, já podemos ver que estão incorretas as letras “a” e “b”. Quanto à LETRA e, já estamos “carecas” de saber que equivale a uma operação com forma jurídica de aluguel e essência de financiamento, portanto, venda a prazo não faz parte da característica do leasing.\\n\\nVocê poderia ter ficado em dúvidas com relação às letras “c” e “d”. De olho fechado, podemos marcar a LETRA d, em conformidade com os conceitos vimos.\\n\\n- Professor, e a LETRA c?\\n\\n- Confesso que nunca tinha ouvido essa palavra “Enfiteuse”.\\n\\nNada melhor que aprender conceitos novos. Vejamos:\\n\\n“Enfiteuse é um direito real sobre coisas alheias, bem amplo inclusive, pois garante a posse, a fruição, transmissão por herança e até a alienação, ou seja, é o domínio útil. Ou ainda; enfiteuse é o negócio jurídico no qual o proprietário (denominado senhorio) passa para o adquirente (denominado enfiteuta) o domínio útil de bem imóvel mediante o pagamento de foro anual, cuja relação tem caráter perpétuo.”\\n\\nASADDASDAS52S BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa Aula 04 (Somente em PDF)\\n\\nPortanto, há algumas diferenças entre Enfiteuse e Arrendamento, quais sejam:\\n\\nEnfiteuse Arrendamento\\n\\nPerpétuo Temporário\\n\\nDomínio Útil Posse, Uso e Gozo.\\n\\nDireito Real Relação Obrigacional\\n\\nSenhorio e Enfiteuta Arrendador e Arrendatário\",\"o\":[\"transfere apenas os benefícios.\",\"transfere apenas os riscos.\",\"transfere apenas a enfiteuse.\",\"não realiza essa transferência.\",\"equivale a uma venda a prazo.\"],\"g\":3},{\"_id\":1,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"COMPANHIA ESTADUAL DE HABITAÇÃO PUPULAR PB Contador · 2009\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"No Brasil,\\nhá duas modalidades de arrendamento mercantil utilizadas: o leasing operacional e o financeiro.\\nAcerca desse assunto, assinale a opção correta.\",\"c\":\"a) A operação de arrendamento mercantil que transfere ao arrendatário substancialmente todos\\n\\nos riscos inerentes ao uso do bem arrendado, como obsolescência tecnológica e desgastes, é\\n\\nASADDASDAS52S BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa Aula 04 (Somente em PDF)\\n\\ndenominada leasing financeiro;\\n\\nb) Item correto. Conforme art.6º da Res. 2.309/96: considera-se arrendamento mercantil\\n\\noperacional a modalidade em que as contraprestações a serem pagas pela arrendatária contemplem o custo de arrendamento do bem e os serviços inerentes a sua colocação à disposição da arrendatária, não podendo o valor presente dos pagamentos ultrapassar 90% (noventa por cento) do custo do bem;\\n\\nc) A modalidade em que o preço para o exercício da opção de compra poderá ser livremente\\n\\npactuado, podendo ser, inclusive, o valor de mercado do bem arrendado na data do exercício da opção de compra, é o leasing financeiro;\\n\\nd) Nas operações de arrendamento mercantil financeiro, as despesas de manutenção, assistência\\n\\ntécnica e serviços correlatos à operacionalidade do bem arrendado são de responsabilidade da arrendatária.\",\"o\":[\"A operação de arrendamento mercantil que transfere ao arrendatário substancialmente todos os riscos inerentes ao uso do bem arrendado, como obsolescência tecnológica e desgastes, é denominada leasing operacional.\",\"Nas operações de leasing operacional, as contraprestações a serem pagas pela arrendatária contemplam o custo de arrendamento do bem e os serviços inerentes à sua colocação à disposição da arrendatária, não podendo o valor presente dos pagamentos ultrapassar 90% do custo do bem.\",\"Nas operações de leasing operacional, o preço para o exercício da opção de compra poderá ser livremente pactuado, podendo ser, inclusive, o valor de mercado do bem arrendado na data do exercício da opção de compra.\",\"Nas operações de arrendamento mercantil financeiro, as despesas de manutenção, assistência técnica e serviços correlatos à operacionalidade do bem arrendado são de responsabilidade da arrendadora.\"],\"g\":1},{\"_id\":2,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"TJ RR Contador · 2012\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O arrendamento mercantil é classificado como financeiro ou\\noperacional. No arrendamento operacional, há transferência substancial de todos os riscos e\\nbenefícios inerentes à propriedade, ao passo que, no financeiro, não há transferência substancial\\nde riscos e benefícios inerentes à propriedade.\\n\\n( ) Certo ( ) Errado\",\"c\":\"como financeiro se ele transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade. Um arrendamento mercantil deve ser classificado como operacional se ele não transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade.\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista BACEN Contábil Financeira · 2000\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item que se segue acerca das\\noperações financeiras de instituições financeiras.\\n\\nNas operações de subarrendamento - ativas - as contraprestações a receber, assim entendidas a\\nsoma de todas as contraprestações a que contratualmente se obrigar o subarrendatário, serão\\nregistradas a débito da adequada conta do desdobramento de subarrendamentos a receber, em\\ncontrapartida da adequada conta retificadora do desdobramento.\\n\\n( ) Certo ( )Errado\",\"c\":\"“1.7.5.1: As contraprestações a receber, assim entendidas a soma de todas as contraprestações a que contratualmente se obriga o subarrendatário, são registradas a débito da adequada conta do desdobramento Subarrendamentos a Receber, em contrapartida com a adequada conta retificadora do desdobramento.”\\n\\nPercebam que as bancas adoram a literalidade das normas. Para isso, disponibilizei ao final da aula a parte do Cosif referente ao arrendamento mercantil. Não deixem de ler!\",\"g\":\"C\"},{\"_id\":4,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"ESAF Analista BACEN Supervisão ADAPTADA · 2002\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A respeito da contabilidade de\\ninstituições financeiras, julgue o item seguinte:\\n\\nAs instituições financeiras e as sociedades de arrendamento mercantil podem realizar repasse\\ninterfinanceiro de recursos captados no exterior a outras instituições e sociedades da espécie.\\n( ) Certo ( )Errado\",\"c\":\"Contudo, essa Resolução foi revogada por outra Resolução (3.844/2010), que alterou esse dispositivo. Contudo, ao meu ver, houve apenas um ajuste na letra da regulamentação, sem prejudicar, portanto, a essência da norma. Vejamos:\\n\\nResolução 2.770/2000, Art. 5º, § 2º: Às instituições financeiras e às sociedades de arrendamento mercantil é facultada a realização de repasse interfinanceiro de recursos captados no exterior a outras instituições e sociedades da espécie.\\n\\nResolução 3.844/2010, Art. 12: As instituições financeiras e as sociedades de arrendamento mercantil podem realizar operações de repasse interfinanceiro, assim entendidas as operações de repasse cujo tomador, no País, seja outra instituição financeira ou sociedade de arrendamento mercantil.\",\"g\":\"C\"},{\"_id\":5,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"AGU Advogado da União · 2012\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No que diz respeito aos livros empresariais e aos\\ncontratos empresariais, julgue o item seguinte.\\n\\nNa modalidade operacional do arrendamento mercantil, as contraprestações e os demais\\npagamentos previstos no contrato e devidos pela arrendatária são normalmente suficientes para\\nque a arrendadora recupere o custo do bem arrendado durante o prazo contratual da operação e,\\nadicionalmente, obtenha retorno sobre os recursos investidos.\\n\\n( ) Certo ( )Errado\",\"c\":\"vez, com o intuito de mostrar-lhes que, além de recorrente, continua caindo em concursos de alto nível, como é o da AGU. Conforme vimos exaustivamente, a questão trata do leasing financeiro, e não operacional.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 07":{"questoesPdf":[{"title":"Questões Extraídas — Consolidação e Demonstrações · Aula 07 (16 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF · Aula 07 · Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 07 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 07 — <b>Consolidação e Demonstrações</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 07 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Técnico Tributário da Receita Estadual SEFAZ RS · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Um técnico tributário, ao\\nanalisar ações judiciais nas quais a empresa XYZ S.A. figura como ré, identificou um processo\\ndecorrente de uma autuação fiscal no valor total de R$ 1.000.000 e cujo julgamento final\\nestava próximo. Considerando que a perda do processo pela XYZ S.A. era provável, os\\nadvogados da empresa e peritos independentes estimaram quatro cenários de probabilidades\\nde desembolsos futuros, como mostra o quadro seguinte.\\n\\ncenário desembolso probabilidade\\n1 R$ 1.000.000 5%\\n2 R$ 800.000 70%\\n3 R$ 500.000 10%\\n4 R$ 300.000 15%\\nNesse caso, a empresa XYZ S.A. deverá reconhecer uma provisão de a)\\n\\nR$ 800.000.\",\"c\":\"Quando se analisa um processo judicial com múltiplos cenários de desembolso futuros, deve-se selecionar o cenário com a maior probabilidade acima de 50% para o reconhecimento de provisão, conforme exemplificado no cenário 2. É importante notar que o método do valor esperado não é aplicável neste caso, uma vez que se refere a um único processo, não a uma grande quantidade de itens.\",\"o\":[\"R$ 1.000.000.\",\"R$ 300.000.\",\"R$ 500.000.\",\"R$ 705.000.\"],\"g\":0},{\"_id\":1,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Técnico Tributário da Receita Estadual SEFAZ RS · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Com relação ao tratamento\\ncontábil, um passivo contingente com “probabilidade possível” de saída de recursos deve\",\"c\":\"No contexto de tratamento contábil, passivos contingentes que têm uma \\\"probabilidade possível\\\" de resultar em saída de recursos devem ser mencionados em notas explicativas, mas não reconhecidos no balanço patrimonial.\",\"o\":[\"ser divulgado em notas explicativas.\",\"ser reconhecido no patrimônio líquido, na conta de reservas.\",\"ser reconhecido no passivo, na conta de ajustes de avaliação patrimonial. BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF Carlos Roberto Correa Aula 07 (Somente em PDF)\",\"não ser reconhecido no balanço patrimonial nem divulgado em notas explicativas.\",\"ser reconhecido no passivo, na conta de provisões.\"],\"g\":0},{\"_id\":2,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Técnico Contabilidade FUB · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Em relação ao registro de operações\\ncontábeisdiversas, julgue o item a seguir.\\n\\nA reversão de provisões não utilizadas para gastos previstos, como danos ambientais, deve\\nser registrada como uma redução no passivo e um aumento em receita, refletindo a baixa da\\nprovisão previamente estabelecida.\",\"c\":\"Quando há uma reversão de provisão temos o reconhecimento de uma receita (crédito em conta de resultado) e a baixa da provisão anteriormente constituída (débito em conta do passivo).\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Técnico Contabilidade FUB · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item seguinte, com base nos\\npronunciamentos técnicos do Comitê de Pronunciamentos Contábeis (CPC).\\n\\nOs ativos contingentes não devem ser objeto de reconhecimento pela contabilidade.\",\"c\":\"Ativos e passivos contingentes não são reconhecidos em demonstrações financeiras. Eles devem ser apenas mencionados em notas explicativas quando existir uma probabilidade possível de ocorrência.\",\"g\":\"C\"},{\"_id\":4,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Auditor Estadual TCM BA · 2018\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Segundo o CPC 25, um passivo deve ser\\nreconhecido quando a sua ocorrência for provável, isto é, quando a probabilidade de\\nsua ocorrência for\",\"c\":\"De acordo com o CPC 25, um passivo deve ser reconhecido quando é mais provável que ocorra do que não, significando que a probabilidade deve ser maior que 50%.\",\"o\":[\"igual a 20%.\",\"superior a 20% e inferior a 30%.\",\"superior a 30% e inferior a 40%.\",\"superior a 40% e inferior a 50%.\",\"superior a 50%.\"],\"g\":4},{\"_id\":5,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Portuário EMAP · 2018\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A empresa X, ré nos processos trabalhistas\\nA, B e C, que discutem a mesma matéria, mas correm em varas trabalhistas distintas,\\nserá provavelmente condenada a pagar as indenizações reclamadas. A tabela a seguir\\nrefere-se aos processos trabalhistas desfavoráveis à empresa X.\\n\\nprocessos desembolso (em R$ mil) probabilidade de ocorrência\\nA 150 75%\\nB 90 55%\\nC 20 85%\\nCom referência à tabela precedente, julgue o item seguinte.\\n\\nNa situação hipotética apresentada, o montante de provisão a ser reconhecido é de R$ 260.000.\",\"c\":\"Como se trata de TRÊS DESFECHOS POSSÍVEIS DE UMA MESMA MATÉRIA, aplica-se o método de estimativa do valor esperado:\\n\\nAplicando o método, temos:\\n\\n(150,000 x 75%) + (90,000 x 55%) + (20,000 x 85%) = R$179,000\",\"g\":\"E\"},{\"_id\":6,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador DPU · 2016\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Caso determinada sociedade empresária estime uma\\nprovisão, em virtude de garantia oferecida por problema no funcionamento inadequado\\nde produto vendido, essa sociedade deverá reconhecer um passivo e uma despesa no\\nmomentoda venda, pelo valor estimado.\",\"c\":\"Em situações onde a empresa oferece garantias por defeitos em produtos vendidos, ela deve reconhecer tanto um passivo quanto uma despesa no momento da venda, com base no valor estimado para cobrir tais garantias.\",\"g\":\"C\"},{\"_id\":7,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Contabilidade e Finanças BACEN · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item a seguir, com\\nbase no Pronunciamento Técnico CPC 25, que trata de provisões, passivos\\ncontingentes e ativoscontingentes.\\n\\nOs ativos contingentes devem ser reconhecidos nas demonstrações contábeis quando for\\npossívela realização de uma estimativa confiável do valor.\",\"c\":\"Ativos contingentes não são reconhecidos nas demonstrações contábeis, uma vez que representam possíveis ativos que dependem da ocorrência de eventos futuros incertos.\",\"g\":\"E\"},{\"_id\":8,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador SUFRAMA · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Acerca dos critérios de mensuração das provisões e\\ndos passivos contingentes, julgue o item subsequente.\\n\\nNo caso dos passivos contingentes, o valor reconhecido deve ser a melhor estimativa dos\\ndispêndios necessários para liquidar a obrigação presente na data da apresentação das\\ndemonstrações contábeis.\",\"c\":\"Passivos contingentes não são reconhecidos nas demonstrações contábeis. Eles devem ser apenas mencionados em notas explicativas, exceto em casos onde a saída de recursos é considerada remota.\",\"g\":\"E\"},{\"_id\":9,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador SUFRAMA · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Uma provisão não deve ser reconhecida se não\\nhouver estimativa confiável do valor da obrigação.\",\"c\":\"Uma provisão deve ser reconhecida quando a empresa tem uma obrigação presente resultante de um evento passado, é provável que seja necessária uma saída de recursos, e o valor da obrigação pode ser estimado com confiabilidade.\",\"g\":\"C\"},{\"_id\":10,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador SUFRAMA · 2014\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Acerca dos itens tratados nos\\npronunciamentos técnicos do Comitê de Pronunciamentos Contábeis (CPC), julgue o\\nitem a seguir.\\n\\nDe acordo com as definições do CPC, um ativo contingente surge de eventos não planejados ou\\nnão esperados que possibilitem a entrada de benefícios econômicos para a entidade.\",\"c\":\"Ativos contingentes surgem de eventos inesperados que podem resultar em benefícios econômicos futuros, mas não são reconhecidos nas demonstrações financeiras até que seja quase certo que os benefícios serão realizados.\",\"g\":\"C\"},{\"_id\":11,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador TCE RO · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação à estrutura conceitual do Comitê de\\nPronunciamentos Contábeis (CPC), julgue o item a seguir.\\n\\nO passivo cuja avaliação é realizada mediante a utilização de um grau significativo de\\nestimativas é denominado provisões, as quais são reconhecidas no balanço patrimonial se\\nsatisfizerem os critérios de definição de passivo, como representar uma obrigação presente.\",\"c\":\"Provisões são reconhecidas no balanço patrimonial quando satisfazem critérios específicos de reconhecimento de passivo, indicando uma obrigação presente que provavelmente exigirá a saída de recursos.\",\"g\":\"C\"},{\"_id\":12,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador TCE RO · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item, relativo aos impactos no\\npatrimônio deuma companhia aberta.\\n\\nAtivos contingentes devem ser reconhecidos na contabilidade sempre que for possível a entrada\\nde benefícios futuros para a empresa. Desse modo, a contrapartida do reconhecimento desses\\nativos deve ocorrer em uma conta de receita.\",\"c\":\"Segundo o CPC 25, Ativo Contingente é um ativo possível que resulta de eventos passados e cuja existência será confirmada apenas pela ocorrência ou não de um ou mais eventos futuros incertos não totalmente sob controle da entidade. Referida Norma estabelece que os ativos contingentes não devem ser contabilizados (reconhecidos nas demonstrações contábeis) , uma vez que pode tratar-se de resultado que nunca venha a ser realizado. Porém, quando a realização do ganho é praticamente certa, então o ativo relacionado não é um ativo contingente e o seu reconhecimento é adequado.\",\"g\":\"E\"},{\"_id\":13,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador TCE RO · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Julgue o item, relativo aos impactos no\\npatrimônio deuma companhia aberta.\\n\\nUma empresa que fabrique e venda eletrodomésticos com garantia contra prováveis defeitos,\\nse julgar provável que tais defeitos venham a ocorrer em alguns itens, deve registrar uma\\nprovisãopara garantias, a qual, simultaneamente, reduzirá o resultado da empresa e aumentará\\no valor dosseus passivos exigíveis.\",\"c\":\"A constituição de uma provisão para garantias implica o reconhecimento de uma despesa e o aumento do passivo, refletindo a expectativa de gastos futuros com defeitos de produtos.\",\"g\":\"C\"},{\"_id\":14,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Contador MJ · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considerando os pronunciamentos técnicos do\\nComitê dePronunciamentos Contábeis (CPC), julgue o item seguinte.\\n\\nAs provisões são obrigações presentes que devem ser reconhecidas como passivos, desde que\\nse possa fazer uma estimativa razoável do seu valor. Os passivos contingentes, no entanto, por\\nrepresentarem obrigações possíveis ou obrigações que não atendem aos critérios de\\nreconhecimento estabelecidos pelo CPC, não são reconhecidos como passivos na\\ncontabilidade.\\n\\nBACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF\\nCarlos Roberto Correa\\nAula 07 (Somente em PDF)\",\"c\":\"Provisões são reconhecidas como passivos quando existe uma obrigação presente e é provável a necessidade de saída de recursos, enquanto passivos contingentes não são reconhecidos devido à sua natureza incerta.\",\"g\":\"C\"},{\"_id\":15,\"t\":\"Questões Aula\",\"b\":\"Diversas\",\"src\":\"Analista Judiciário Contabilidade TRT 10 · 2013\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Com relação às demonstrações\\ncontábeis e aos pronunciamentos técnicos do Comitê de Pronunciamentos Contábeis,\\njulgue o item que se segue.\\n\\n\\nDeve-se reconhecer uma provisão para passivo contingente, caso a entidade preveja a\\nnecessidade, ainda que remota, de uma saída de recursos que incorporem benefícios\\neconômicospara liquidar determinada obrigação.\",\"c\":\"Passivos contingentes não são reconhecidos como passivo porque são:\\n\\n▪ obrigações possíveis, visto que ainda há de ser confirmado se a entidade tem ou não uma obrigação presente que possa conduzir a uma saída de recursos que incorporam benefícioseconômicos; ou ▪ obrigações presentes que não satisfazem os critérios de reconhecimento da Norma (porque não é provável que seja necessária uma saída de recursos que incorporem benefícios econômicos para liquidar a obrigação, ou não pode ser feita uma estimativa suficientementeconfiável do valor da obrigação).\\n\\nConforme estudamos, não se deve reconhecer um passivo contingente, apenas divulgá-lo. Porém, se a possibilidade de uma saída de recursos que incorporam benefícios econômicos for remota não há nem divulgação.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 05":{"questoesPdf":[{"title":"Questões Extraídas — Ativos Não Financeiros Mantidos para Venda e Intangíveis · Aula 05 (20 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF Aula 05 — Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 05 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 05 — <b>Ativos Não Financeiros Mantidos para Venda e Intangíveis</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 05 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Segundo a Resolução CMN nº 4.747, de 29 de agosto de 2019, os ativos não financeiros mantidos para venda devem ser obrigatoriamente mensurados pelo seu valor contábil bruto, sem considerar as despesas de venda.\",\"c\":\"A Resolução CMN nº 4.747/2019 estabelece que os ativos não financeiros mantidos para venda devem ser mensurados pelo menor valor entre o seu valor contábil líquido e o valor justo menos as despesas de venda. Isso significa que as despesas de venda devem ser consideradas na mensuração do valor desses ativos, o que está em consonância com os princípios do padrão internacional IFRS 5. Este critério visa refletir de maneira mais precisa o valor líquido que a entidade espera recuperar através da venda desses ativos.\",\"g\":\"E\"},{\"_id\":1,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A Resolução CMN nº 4.747, de 29 de agosto de 2019, alinha as práticas contábeis brasileiras aos padrões internacionais do IASB, especialmente no que se refere ao tratamento contábil de ativos não financeiros mantidos para venda, anteriormente regulamentados sob uma perspectiva diferente pelo Cosif.\",\"c\":\"A Resolução CMN nº 4.747/2019 foi criada para alinhar as práticas contábeis brasileiras aos padrões internacionais estabelecidos pelo IASB, particularmente em relação ao tratamento de ativos não financeiros mantidos para venda. Anteriormente, esses ativos eram tratados sob normas específicas estabelecidas pelo Cosif, que, apesar de seguirem boas práticas contábeis, não estavam totalmente alinhadas com o padrão internacional IFRS 5. A nova resolução busca simplificar os critérios de registro desses ativos, adotando princípios baseados nos padrões internacionais e prevendo o valor justo como forma de mensuração.\",\"g\":\"C\"},{\"_id\":2,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Um ativo não financeiro mantido para venda deve estar disponível para venda imediata em suas condições atuais e sua alienação deve ser altamente provável no período máximo de um ano.\",\"c\":\"Para ser classificado como um ativo não financeiro mantido para venda, o ativo deve estar disponível para venda imediata nas condições em que se encontra e a sua venda deve ser considerada altamente provável dentro de um período máximo de um ano, conforme estabelecido pela Resolução.\",\"g\":\"C\"},{\"_id\":3,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os ativos não financeiros mantidos para venda devem ser sempre avaliados pelo seu valor justo líquido de despesas de venda, independentemente de outras considerações.\",\"c\":\"Os ativos não financeiros mantidos para venda devem ser avaliados pelo menor valor entre o valor contábil líquido do ativo (deduzidas as provisões para perdas por redução ao valor recuperável e a depreciação ou amortização acumulada) e o valor justo do ativo, líquido de despesas de vendas. Essa avaliação considera tanto o valor contábil líquido quanto o valor justo, ao contrário de se basear unicamente no valor justo.\",\"g\":\"E\"},{\"_id\":4,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"É permitido o reconhecimento de depreciação ou de amortização relativas aos ativos não financeiros mantidos para venda.\",\"c\":\"A Resolução CMN nº 4.747 veda explicitamente o reconhecimento de depreciação ou de amortização relativas aos ativos não financeiros mantidos para venda, visando a consistência na avaliação desses ativos até que sejam efetivamente vendidos ou reclassificados.\",\"g\":\"E\"},{\"_id\":5,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Se um ativo não financeiro mantido para venda não for vendido dentro de um ano, ele deve ser automaticamente baixado do balanço patrimonial.\",\"c\":\"Caso um ativo não financeiro mantido para venda não seja vendido dentro do período de um ano, ele não é baixado do balanço patrimonial, mas deve ser reclassificado para o adequado grupamento contábil do ativo não circulante realizável a longo prazo. Essa reclassificação permite que o ativo continue sendo reconhecido no balanço patrimonial, refletindo Carlos Roberto Correa Aula 05 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br uma mudança na estimativa do prazo para sua venda.\",\"g\":\"E\"},{\"_id\":6,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A Resolução BCB nº 5, de 12 de agosto de 2020, estabelece que os ativos não financeiros mantidos para venda pelas administradoras de consórcio e instituições de pagamento devem ser reclassificados para o ativo circulante apenas se a venda for considerada improvável dentro de um ano.\",\"c\":\"A Resolução BCB nº 5 estabelece que os ativos não financeiros mantidos para venda devem ser reclassificados para a adequada rubrica contábil do ativo circulante na data em que a administradora de consórcios ou a instituição de pagamento decidir vendê-los, desde que sua venda seja considerada altamente provável dentro do período máximo de um ano. Isso implica que a reclassificação para o ativo circulante ocorre sob a expectativa de uma venda provável e não improvável.\",\"g\":\"E\"},{\"_id\":7,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Administradoras de consórcio e instituições de pagamento são obrigadas a reconhecer qualquer ganho por aumento no valor justo líquido de despesa de vendas dos ativos mantidos para venda, sem limitações.\",\"c\":\"Administradoras de consórcio e instituições de pagamento podem reconhecer o ganho por aumento no valor justo líquido de despesa de vendas do ativo ocorrido posteriormente à reavaliação, mas esse reconhecimento de ganho está limitado à perda por redução ao valor recuperável acumulada reconhecida em períodos anteriores. Isso significa que o reconhecimento de ganhos é restrito até o montante de qualquer perda reconhecida anteriormente, garantindo que a recuperação de valor não exceda as perdas reconhecidas previamente para o mesmo ativo.\",\"g\":\"E\"},{\"_id\":8,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os ativos imobilizados são bens de uma empresa com vida útil superior a um ano, destinados ao seu funcionamento normal.\",\"c\":\"Os ativos imobilizados incluem bens como terrenos, edifícios, máquinas e Carlos Roberto Correa Aula 05 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br equipamentos, veículos, móveis e utensílios, computadores e software, adquiridos pela empresa para serem utilizados na produção ou fornecimento de mercadorias e serviços, para locação a terceiros, ou para fins administrativos.\",\"g\":\"C\"},{\"_id\":9,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Terrenos são um exemplo de ativos imobilizados que geralmente não são depreciados.\",\"c\":\"Diferentemente de outros ativos imobilizados, os terrenos geralmente não são sujeitos à depreciação porque não perdem valor ao longo do tempo devido ao uso, desgaste ou obsolescência.\",\"g\":\"C\"},{\"_id\":10,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A depreciação é o processo de alocação sistemática do valor de um ativo imobilizado ao longo de sua vida útil.\",\"c\":\"A depreciação reconhece a diminuição do valor dos ativos imobilizados ao longo do tempo, exceto terrenos, e é calculada e registrada periodicamente.\",\"g\":\"C\"},{\"_id\":11,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Gastos incorridos para manter os ativos imobilizados em condições normais de uso aumentam sua capacidade de produção ou período de vida útil e, portanto, devem ser capitalizados.\",\"c\":\"Gastos para manter os ativos imobilizados em condições normais de uso, que não aumentam sua capacidade de produção ou período de vida útil, devem ser reconhecidos como despesas do período em que ocorrerem, e não capitalizados.\",\"g\":\"E\"},{\"_id\":12,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Segundo a Resolução BCB nº 6, de 12 de agosto de 2020, as administradoras de consórcio e as instituições de pagamento não precisam registrar os bens tangíveis próprios e as benfeitorias realizadas em imóveis de terceiros no ativo imobilizado.\",\"c\":\"A Resolução BCB nº 6 estabelece que tanto as administradoras de consórcio quanto as instituições de pagamento devem registrar esses bens e benfeitorias no ativo imobilizado, desde que sejam destinados à manutenção de suas atividades por mais de um exercício social.\",\"g\":\"E\"},{\"_id\":13,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A baixa de um ativo imobilizado só ocorre quando o ativo é alienado, e não quando não há mais expectativas de benefícios econômicos futuros.\",\"c\":\"A baixa de um ativo imobilizado ocorre tanto quando o ativo é alienado quanto quando não há mais expectativas de benefícios econômicos futuros de sua utilização ou alienação.\",\"g\":\"E\"},{\"_id\":14,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os bens tangíveis recebidos em doação devem ser registrados pelo valor contábil anterior do doador.\",\"c\":\"Bens tangíveis recebidos em doação devem ser registrados pelo seu valor de mercado na data de recebimento, refletindo o justo valor.\",\"g\":\"E\"},{\"_id\":15,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A amortização de um ativo intangível com vida útil indefinida deve ser realizada de forma linear ao longo de um período estimado, baseado em análise anual.\",\"c\":\"Ativos intangíveis caracterizados como de vida útil indefinida não são amortizáveis. Eles devem ser avaliados anualmente quanto à possível diminuição de valor, mas não estão sujeitos a um processo de amortização linear ou de outro tipo.\",\"g\":\"E\"},{\"_id\":16,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os ativos intangíveis recebidos em doação devem ser registrados pelo valor de mercado em contrapartida ao resultado do período, independentemente de sua destinação ou finalidade.\",\"c\":\"Ativos intangíveis recebidos em doação são registrados pelo seu valor de mercado no momento da doação. Este registro é realizado em contrapartida ao resultado do período, refletindo corretamente o valor justo do ativo recebido sem custo de aquisição.\",\"g\":\"C\"},{\"_id\":17,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Para ativos intangíveis com vida útil definida, é aceitável que o valor residual seja estimado como uma porcentagem significativa do custo de aquisição.\",\"c\":\"Geralmente, presume-se que o valor residual de ativos intangíveis é zero, a menos que exista um compromisso firme de terceiros para a compra do ativo ao final de sua vida útil ou um mercado ativo que permita uma estimativa confiável desse valor. Assim, não é comum estimar o valor residual como uma porcentagem significativa do custo de aquisição sem evidências claras dessas condições.\",\"g\":\"E\"},{\"_id\":18,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Gastos subsequentes ao reconhecimento inicial de um ativo intangível que aumentam significativamente a sua capacidade de geração de benefícios econômicos futuros podem ser capitalizados e adicionados ao valor contábil do ativo.\",\"c\":\"Gastos subsequentes que resultam em um aumento claro na capacidade de geração de benefícios econômicos futuros do ativo intangível podem ser capitalizados. Isso inclui gastos que elevam a eficiência, produtividade ou prazo de vida útil econômica do ativo, e devem ser agregados ao valor contábil do ativo.\",\"g\":\"C\"},{\"_id\":19,\"t\":\"Ativos Não Financeiros e Intangíveis\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O registro de um ativo intangível desenvolvido internamente é permitido apenas quando a instituição é capaz de demonstrar a intenção e capacidade de concluir o ativo, mas não é necessário demonstrar a existência de um mercado para os produtos ou serviços gerados pelo ativo.\",\"c\":\"Para o reconhecimento de um ativo intangível desenvolvido internamente, é essencial que a instituição não apenas demonstre a viabilidade técnica, a intenção e a capacidade de concluir e usar o ativo, mas também que exista um mercado para os produtos ou serviços gerados pelo ativo. Isso ajuda a garantir que haverá benefícios econômicos futuros atribuíveis ao ativo.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 06":{"questoesPdf":[{"title":"Questões Extraídas — Grupos de Consórcio · Aula 06 (47 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF Aula 06 — Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 06 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 06 — <b>Grupos de Consórcio</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 06 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Um consórcio é um agrupamento de indivíduos e entidades organizado exclusivamente para a aquisição de imóveis.\",\"c\":\"Um consórcio pode ser usado para adquirir uma variedade de bens ou serviços, incluindo imóveis, veículos, serviços de cirurgia estética e viagens.\",\"g\":\"E\"},{\"_id\":1,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os grupos de consórcio são caracterizados pela cobrança de juros sobre as contribuições mensais.\",\"c\":\"Os consórcios são conhecidos pela ausência de juros, cobrando apenas uma taxa de administração.\",\"g\":\"E\"},{\"_id\":2,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O Banco Central do Brasil é o órgão responsável por regular as administradoras de consórcio.\",\"c\":\"O Banco Central tem autoridade para estabelecer normas, coordenar, supervisionar, fiscalizar e controlar as operações de consórcio.\",\"g\":\"C\"},{\"_id\":3,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A escrituração dos grupos de consórcio deve ser feita de forma coletiva e não individualizada por grupo.\",\"c\":\"A escrituração dos grupos de consórcio deve ser individualizada por grupo.\",\"g\":\"E\"},{\"_id\":4,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Durante a liquidação extrajudicial, os ativos da empresa devem ser mensurados pelo valor contábil líquido. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"Os ativos devem ser mensurados pelo menor valor entre o valor contábil líquido e o valor líquido provável de realização.\",\"g\":\"E\"},{\"_id\":5,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições em regime de liquidação extrajudicial estão dispensadas da elaboração e publicação de balancetes patrimoniais mensais.\",\"c\":\"Essas instituições estão dispensadas dessa obrigação.\",\"g\":\"C\"},{\"_id\":6,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Todas as instituições financeiras, sem exceção, são obrigadas a ter suas demonstrações financeiras auditadas por auditores independentes.\",\"c\":\"Existem exceções, como as sociedades de crédito ao microempreendedor e à empresa de pequeno porte.\",\"g\":\"E\"},{\"_id\":7,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A auditoria interna é realizada por profissionais ou empresas internas e externas à instituição auditada.\",\"c\":\"A auditoria interna é executada pela própria instituição, diferentemente da auditoria independente que é realizada por entidades externas.\",\"g\":\"E\"},{\"_id\":8,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A auditoria independente visa trazer uma opinião imparcial sobre as demonstrações financeiras da instituição auditada.\",\"c\":\"Este é o objetivo principal da auditoria independente.\",\"g\":\"C\"},{\"_id\":9,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A supervisão auxiliar realizada pelas cooperativas centrais de crédito em suas singulares é um tipo de auditoria interna.\",\"c\":\"Embora possa ser confundida com auditoria interna, a supervisão auxiliar tem papéis e responsabilidades distintas.\",\"g\":\"E\"},{\"_id\":10,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As instituições financeiras podem contratar um auditor independente mesmo que esteja configurada uma situação de impedimento. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"São vedadas a contratação e a manutenção de auditor independente em situações de impedimento ou incompatibilidade.\",\"g\":\"E\"},{\"_id\":11,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O conceito de firma em rede não influencia as regras de independência do auditor.\",\"c\":\"As regras de independência também se aplicam às firmas em rede, conforme definido na regulamentação.\",\"g\":\"E\"},{\"_id\":12,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"É permitida a participação direta ou indireta do auditor independente no capital da instituição auditada.\",\"c\":\"Esta situação é considerada um impedimento à contratação do auditor independente.\",\"g\":\"E\"},{\"_id\":13,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A regulamentação permite que os honorários do auditor independente representem uma grande parte de seu faturamento total.\",\"c\":\"Se os honorários representarem 25% ou mais do faturamento da empresa de auditoria independente, isso pode comprometer a sua independência.\",\"g\":\"E\"},{\"_id\":14,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições financeiras devem verificar continuamente outras possíveis situações que possam afetar a independência do auditor.\",\"c\":\"Tanto as instituições financeiras quanto os auditores devem verificar continuamente a independência.\",\"g\":\"C\"},{\"_id\":15,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A substituição do auditor independente é obrigatória após emitidos relatórios relativos a três exercícios sociais completos e consecutivos.\",\"c\":\"A substituição é obrigatória após cinco exercícios sociais completos e consecutivos. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br 17) O intervalo mínimo para o retorno de um auditor independente após substituição é de um exercício social completo. Resposta: Errado. O intervalo mínimo é de três exercícios sociais completos.\",\"g\":\"E\"},{\"_id\":16,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A contratação ou manutenção de auditor independente fica condicionada à habilitação do responsável técnico pela auditoria.\",\"c\":\"A habilitação depende de aprovação em exame de certificação e cumprimento de requisitos específicos.\",\"g\":\"C\"},{\"_id\":17,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O Banco Central do Brasil pode executar controles de qualidade externos sobre a auditoria independente.\",\"c\":\"O Banco Central tem autoridade para realizar controles de qualidade externos.\",\"g\":\"C\"},{\"_id\":18,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As instituições financeiras não precisam comunicar ao Banco Central do Brasil a contratação e a substituição do auditor independente.\",\"c\":\"As instituições devem informar ao Banco Central a contratação e a substituição do auditor.\",\"g\":\"E\"},{\"_id\":19,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A auditoria independente das demonstrações financeiras é facultativa no ano de autorização para funcionamento da instituição.\",\"c\":\"Existe a possibilidade de dispensa da auditoria independente para o ano de autorização.\",\"g\":\"C\"},{\"_id\":20,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As administradoras de consórcio estão isentas de seguir as diretrizes de auditoria independente estabelecidas pelo COSIF.\",\"c\":\"As administradoras de consórcio também devem seguir diretrizes específicas de auditoria independente. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br 23) Instituições financeiras devem substituir o auditor independente imediatamente após a identificação de qualquer situação que possa comprometer sua independência. Resposta: Certo. A substituição deve ocorrer para corrigir tal situação.\",\"g\":\"E\"},{\"_id\":21,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"É permitido que um membro da equipe de auditoria independente ocupe um cargo de gerência na instituição auditada imediatamente após a auditoria.\",\"c\":\"Existe uma vedação à contratação de pessoal-chave da equipe de auditoria para cargos que possam influenciar a gestão da instituição dentro de um período de 12 meses após a auditoria.\",\"g\":\"E\"},{\"_id\":22,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Auditores independentes não são obrigados a documentar e manter uma política de independência.\",\"c\":\"Os auditores devem documentar e manter uma política de independência, disponibilizando-a ao Banco Central e ao comitê de auditoria da instituição auditada.\",\"g\":\"E\"},{\"_id\":23,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O comitê de auditoria é opcional para todas as instituições financeiras e outras entidades autorizadas a funcionar pelo Banco Central do Brasil.\",\"c\":\"A constituição de um comitê de auditoria é obrigatória para determinadas instituições, conforme critérios específicos.\",\"g\":\"E\"},{\"_id\":24,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições financeiras e demais entidades autorizadas a funcionar pelo Banco Central do Brasil estão isentas da obrigação de fornecer uma representação formal da administração ao auditor independente.\",\"c\":\"É obrigatório que a administração dessas instituições forneça uma representação formal alinhada com as normas de auditoria estabelecidas pelo Conselho Federal de Contabilidade.\",\"g\":\"E\"},{\"_id\":25,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O conselho de administração não possui responsabilidade na escolha e destituição dos auditores independentes. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"A escolha e a destituição dos auditores independentes estão a cargo do conselho de administração.\",\"g\":\"E\"},{\"_id\":26,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A contratação de auditor independente que não atenda aos requisitos regulatórios não implica responsabilidade para os membros do conselho de administração.\",\"c\":\"Os membros do conselho de administração serão responsabilizados pela contratação de um auditor independente que não atenda aos requisitos regulatórios.\",\"g\":\"E\"},{\"_id\":27,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Auditorias realizadas em descumprimento das normas estabelecidas para a auditoria independente são consideradas válidas para fins de cumprimento das diretrizes do Conselho Monetário Nacional e do Banco Central do Brasil.\",\"c\":\"As auditorias realizadas em descumprimento dessas normas são consideradas sem efeito.\",\"g\":\"E\"},{\"_id\":28,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A diretoria das instituições é dispensada da obrigação de comunicar formalmente ao auditor independente e ao comitê de auditoria qualquer suspeita ou ocorrência de irregularidades.\",\"c\":\"A diretoria das instituições é obrigada a comunicar formalmente e em tempo hábil essas informações.\",\"g\":\"E\"},{\"_id\":29,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições sem um comitê de auditoria estabelecido não precisam designar um diretor responsável perante o Banco Central do Brasil para assegurar a aderência às normas de auditoria independente.\",\"c\":\"É necessário designar um diretor responsável nessas circunstâncias.\",\"g\":\"E\"},{\"_id\":30,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O Banco Central do Brasil não tem autoridade para exigir a substituição de auditores independentes em caso de descumprimento das normas estabelecidas.\",\"c\":\"O Banco Central tem autoridade para exigir a substituição nesses casos. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br 34) Instituições financeiras são obrigadas a informar ao Banco Central do Brasil apenas a contratação, mas não a substituição do auditor independente. Resposta: Errado. As instituições devem informar tanto a contratação quanto a substituição.\",\"g\":\"E\"},{\"_id\":31,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A dispensa da auditoria independente para as demonstrações financeiras aplica-se a todos os anos de operação da instituição.\",\"c\":\"A dispensa aplica-se apenas ao ano de autorização para funcionamento da instituição.\",\"g\":\"E\"},{\"_id\":32,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições financeiras podem manter auditores independentes que estejam sob proibição legal de prestar serviços.\",\"c\":\"As instituições não podem manter auditores que estejam sob proibição legal.\",\"g\":\"E\"},{\"_id\":33,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições financeiras não precisam manter documentação comprobatória do cumprimento das diretrizes de auditoria independente.\",\"c\":\"As instituições devem manter documentação comprobatória disponível para o Banco Central.\",\"g\":\"E\"},{\"_id\":34,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A constituição de um comitê de auditoria é facultativa para as instituições financeiras registradas como companhias abertas.\",\"c\":\"A constituição é obrigatória para essas instituições.\",\"g\":\"E\"},{\"_id\":35,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As regras de independência do auditor não se aplicam às firmas de auditoria em rede.\",\"c\":\"As regras de independência se aplicam também às firmas em rede.\",\"g\":\"E\"},{\"_id\":36,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As instituições financeiras podem realizar operações de crédito com auditores independentes sob qualquer condição. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"As operações de crédito são permitidas apenas em condições de mercado normais.\",\"g\":\"E\"},{\"_id\":37,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A auditoria independente não requer a aprovação em um exame de certificação específico para os responsáveis técnicos pela auditoria.\",\"c\":\"A habilitação para os responsáveis técnicos depende da aprovação em um exame de certificação específico.\",\"g\":\"E\"},{\"_id\":38,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Auditores independentes podem ser contratados mesmo que seus honorários representem uma grande parte do faturamento da instituição auditada.\",\"c\":\"Isso pode comprometer a independência do auditor.\",\"g\":\"E\"},{\"_id\":39,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A independência do auditor não precisa ser verificada continuamente pelas instituições financeiras.\",\"c\":\"A independência deve ser verificada continuamente.\",\"g\":\"E\"},{\"_id\":40,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A substituição do auditor independente é necessária imediatamente após a auditoria.\",\"c\":\"A substituição é obrigatória após cinco exercícios sociais completos e consecutivos.\",\"g\":\"E\"},{\"_id\":41,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O intervalo mínimo para o retorno de um auditor independente após substituição é de cinco anos.\",\"c\":\"O intervalo mínimo é de três exercícios sociais completos.\",\"g\":\"E\"},{\"_id\":42,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições financeiras devem informar ao Banco Central apenas a contratação do auditor independente. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"As instituições devem informar tanto a contratação quanto a substituição.\",\"g\":\"E\"},{\"_id\":43,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A documentação comprobatória do cumprimento das diretrizes de auditoria independente deve ser mantida por três anos após o término dos serviços.\",\"c\":\"A documentação deve ser mantida por cinco anos após o término dos serviços.\",\"g\":\"E\"},{\"_id\":44,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os auditores independentes são obrigados a seguir apenas as diretrizes do Banco Central do Brasil, desconsiderando as normas do Conselho Federal de Contabilidade.\",\"c\":\"Os auditores devem seguir as diretrizes do Banco Central, do Conselho Federal de Contabilidade e de outras entidades reguladoras relevantes.\",\"g\":\"E\"},{\"_id\":45,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A constituição de um comitê de auditoria é obrigatória para todas as instituições financeiras, sem exceção.\",\"c\":\"Existem critérios específicos que determinam a obrigatoriedade da constituição de um comitê de auditoria.\",\"g\":\"E\"},{\"_id\":46,\"t\":\"Consórcios\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A supervisão auxiliar realizada pelas cooperativas centrais de crédito é considerada um tipo de auditoria externa.\",\"c\":\"A supervisão auxiliar é distinta da auditoria interna e externa, servindo como um mecanismo de supervisão complementar. Carlos Roberto Correa Aula 06 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 08":{"questoesPdf":[{"title":"Questões Extraídas — Patrimônio Líquido e Remuneração do Capital Próprio · Aula 08 (20 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF Aula 08 — Questões Aula</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 08 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 08 — <b>Patrimônio Líquido e Remuneração do Capital Próprio</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 08 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Patrimônio Líquido\",\"b\":\"CESPE\",\"src\":\"TJ-ES/técnico de Contabilidade/CESPE\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O patrimônio líquido tanto pode apresentar saldo credor quanto devedor.\",\"c\":\"a situação líquida negativa (Ativo – Passivo < 0), também chamada de passivo a descoberto, indica que os componentes do ativo não são suficientes para cobrir as obrigações. Na prática, costumamos dizer que a instituição está com o patrimônio “virado”. Uma instituição financeira com o patrimônio virado provavelmente será liquidada 7 pelo Banco central.\",\"g\":\"C\"},{\"_id\":1,\"t\":\"Patrimônio Líquido\",\"b\":\"FCC\",\"src\":\"TRT – 6ª/Analista/FCC\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A conta do capital social discriminará o montante subscrito e, por dedução, a parcela ainda não realizada.\",\"c\":\"o montante do capital subscrito é evidenciado pela rubrica contábil 6.1.1.10.00-1 CAPITAL, e a parcela não realizada pela 6.1.1.50.00-9 CAPITAL A REALIZAR.\",\"g\":\"C\"},{\"_id\":2,\"t\":\"Patrimônio Líquido\",\"b\":\"CESPE\",\"src\":\"SESA-ES/Contador/CESPE\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Todas as contas de reservas de capital devem ser constituídas ou aumentadas com contrapartidas em contas de resultado.\",\"c\":\"estejam atentos, pessoal! As contrapartidas da conta Reservas de Capital não transitam pelo resultado .\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Segundo o Cosif, para fins de constituição de reservas de reavaliação, apenas os ativos permanentes imobilizados próprios para uso nas atividades fins da instituição são passíveis de reavaliação.\",\"c\":\"a regra é clara, pessoal. Segundo o Cosif: “Fica vedada às instituições financeiras e demais instituições autorizadas a funcionar pelo Banco Central do Brasil a realização de reavaliação de ativos de uso próprio e a constituição das respectivas reservas de reavaliação.” Vejam que não há exceção!\",\"g\":\"E\"},{\"_id\":4,\"t\":\"Patrimônio Líquido\",\"b\":\"CESPE\",\"src\":\"Prefeitura de Vitória/Auditor Fiscal do Tesouro Municipal /CESPE\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Considere que, após a apuração do resultado do exercício e antes da constituição das reservas, o patrimônio líquido de uma companhia fosse composto como a seguir. Capital social . . . . . . . . . . . . . . . . . . . . . R$ 5.000.000,00 Reserva legal . . . . . . . . . . . . . . . . . . . . . R$ 1.000.000,00 Outras reservas de lucros . . . . . . . . . . . . . . R$ 500.000,00 Nessa situação, e sabendo-se que o lucro líquido do exercício foi de R$ 2.000.000,00, é correto concluir que a empresa poderá destinar R$ 100.000,00 à reserva legal.\",\"c\":\"se a questão falar em constituição de reserva legal, temos de considerar os limites obrigatórios e facultativos. Lembram-se deles? Pois bem! Percebam que a reserva legal já atingiu o limite obrigatório de 20% do capital social (20% de R$ 5.000.000,00 = R$ 1.000.000,00). Nessa situação, a instituição não poderá destinar parcela do lucro líquido para constituição de reserva legal.\",\"g\":\"E\"},{\"_id\":5,\"t\":\"Patrimônio Líquido\",\"b\":\"CESPE\",\"src\":\"SESA-ES/Contador/CESPE\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A conta de reserva legal e a conta provisão para contingências devem ser classificadas no mesmo grupo de contas patrimoniais.\",\"c\":\"pegadinha maldosa da banca. A rubrica contábil 4.9.8.80.80-3 PROVISÃO PARA CONTINGÊNCIA pertence ao Passivo, enquanto a rubrica contábil 6.1.5.30.00-7 RESERVA PARA CONTINGÊNCIAS é conta do Patrimônio Líquido. Não confunda!\",\"g\":\"E\"},{\"_id\":6,\"t\":\"Patrimônio Líquido\",\"b\":\"CESPE\",\"src\":\"TRE-ES/Técnico em Contabilidade/CESPE\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Uma empresa, após ter apurado lucro de R$ 100.000,00, destinou um terço desse valor para contingências futuras. Nessa situação, a empresa contabilizará, no mesmo exercício, R$ 30.000,00 a crédito de uma conta de provisão para contingências.\",\"c\":\"cuidado para não confundirem Reserva para Contingência (Patrimônio Líquido) com Provisão para Contingência (Passivo), pois são duas coisas distintas. Como diria um grande professor meu: “se fosse a mesma coisa não teria dois nomes”. Nes se caso, trata-se de hipótese de Reserva para Contingência, e não de Provisão como afirmou a questão.\",\"g\":\"E\"},{\"_id\":7,\"t\":\"Patrimônio Líquido\",\"b\":\"CESGRANRIO\",\"src\":\"TRANSPETRO/Técnico em Contabilidade/CESGRANRIO\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"As contribuições denominadas reservas de capital NÃO:\",\"c\":\"as reservas de capital são constituídas com valores recebidos pela instituição e que não transitam pelo resultado como receitas ou ganhos , ou seja, não foram recebidas por meio de sua atividade-fim. Essas reservas são formadas pela contribuição por meio da subscrição de valores mobiliários da própria instituição, enquanto tais valores não forem destinados a integrar o capital social.\",\"o\":[\"São transferidas para o capital;\",\"Registram ágio na emissão de ações;\",\"Transitam pelos resultados;\",\"Absorvem prejuízos;\",\"Resgatam partes beneficiárias.\"],\"g\":2},{\"_id\":8,\"t\":\"Patrimônio Líquido\",\"b\":\"CESGRANRIO\",\"src\":\"PETROBRÁS/Técnico em Contabilidade/CESGRANRIO\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O objetivo da constituição da Reserva de Lucros a Realizar, previsto na Lei nº 6.404/74, com as alterações inseridas pela Lei nº 11.638/2007, é:\",\"c\":\"conforme visto nesta aula, o objetivo de constituir essa reserva é não distribuir dividendos obrigatórios sobre a parcela de lucros ainda não realizada financeiramente (apesar de contábil e economicamente realizada) pela instituição, quando esses dividendos excederem a parcela financeiramente realizada do lucro líquido do exercício.\",\"o\":[\"dar cobertura a perdas ou despesas cujo fato gerador já ocorreu, sem que tenha havido ainda o correspondente desembolso ou perda, havendo necessidade de efetuar o registro em função do regime de competência;\",\"dar cobertura a perdas ou prejuízos potenciais não repetitivos, ainda não incorridos, mediante segregação de parcelas dos lucros, que seriam distribuídas como dividendos;\",\"permitir a proteção ao credor segregando parcelas dos lucros, que seriam distribuídos em forma de dividendos, quando há incerteza sobre a realização de créditos a receber ainda não incorridos.\",\"permitir o resgate de partes beneficiárias registradas na reserva de capitais, desde que as reservas de lucros constituídas no exercício sejam inferiores ao valor das partes beneficiárias vincendas no exercício.\",\"não distribuir dividendos obrigatórios sobre a parcela de lucros ainda não realizada financeiramente pela companhia, quando tais dividendos excederem a parcela financeiramente realizada do lucro líquido do exercício.\"],\"g\":4},{\"_id\":9,\"t\":\"Patrimônio Líquido\",\"b\":\"CESGRANRIO\",\"src\":\"PETROBRÁS/Técnico em Contabilidade/CESGRANRIO\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"O art. 193 da Lei no 6.404/1976 trata da Reserva Legal e delimita que: o Limite Obrigatório ocorre quando o saldo da conta atingir 20% do valor do Capital Social. O Limite Facultativo ocorre quando o saldo da conta, antes da constituição referente ao exercício em curso, somado ao montante das reservas de capital, atingir 30% do Capital Social. No que diz respeito à reserva legal, atendem plenamente à legislação societária as afirmativas abaixo, EXCETO:\",\"c\":\"a única alternativa errada é a letra “e”. Se o limite obrigatório não for atingido, mas o facultativo sim, a empresa poderá constituir a reserva até atingir o limite obrigatório. O simples atingimento do limite facultativo não proíbe a instituição de constituir nova reserva legal.\",\"o\":[\"Quando nenhum dos dois limites for atingido, a empresa será obrigada a constituir a reserva;\",\"Se o limite obrigatório for atingido antes de calculado o valor da reserva legal do exercício, a empresa não poderá constituir a reserva;\",\"Se o limite obrigatório for atingido no processo de constituição da reserva, a empresa não poderá constituí-la em valor superior a 20% do Capital Social;\",\"Se o limite obrigatório não for atingido, mas o facultativo sim, a empresa poderá decidir por constituir ou não a reserva;\",\"Se o limite obrigatório não for atingido, mas o facultativo sim, a empresa não poderá constituir a reserva. Carlos Roberto Correa Aula 08 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\"],\"g\":4},{\"_id\":10,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"Uma instituição financeira decidiu alienar 10.000 ações, adquiridas por R$ 10,00. O valor pago pelos subscritores foi de R$ 11,00 para cada ação. Considerando exclusivamente os dados apresentados, o lançamento contábil, em reais, de acordo com a legislação vigente, a ser feito é:\",\"c\":\"vamos revisar o que vimos na aula? O lucro apurado na venda das ações em tesouraria contabiliza-se em OUTRAS RESERVAS DE CAPITAL . Ocorrendo prejuízo , este se registra nessa mesma conta , até o limite do saldo originário de lucros em eventuais vendas de lotes anteriores, e o excesso, a débito da própria conta de reserva que deu origem aos recursos para aquisição das ações. Carlos Roberto Correa Aula 08 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br À medida que as ações em tesouraria forem alienadas, tal operação gerará resultados positivos ou negativos e não devem integrar o resultado da empresa. Sendo assim, teríamos o seguinte lançamento contábil: Natureza Código/Conta Título Contábil Valor D 1.1.1.00.00-9 Caixa R$ 110.000,00 C 6.1.9.00.00-8 Ações em Tesouraria R$ 100.000,00 C 6.1.3.99.00-4 Outras Reservas de Capital R$ 10.000,00\",\"o\":[\"D:Caixa (Ativo Circulante)_________________110.000,00 C:Ações em Tesouraria (Patrimônio Líquido)__110.000,00;\",\"D:Caixa (Ativo Circulante)_____________________110.000,00 C:Ações em Tesouraria (Patrimônio Líquido)______100.000,00 C:Outras Reservas de Capital (Patrimônio Líquido)_10.000,00;\",\"D:Caixa (Ativo Circulante)________________________110.000,00 C: Ações em Tesouraria (Patrimônio Líquido)_________100.000,00 C:Reserva de Lucros – Ágio de Ações (Patrimônio Líquido)_10.000,00;\",\"D:Caixa (Ativo Circulante)_________________________110.000,00 C: Ações em Tesouraria (Patrimônio Líquido)__________100.000,00 C:Ajustes de Avaliação Patrimonial (Patrimônio Líquido)__10.000,00;\",\"D:Caixa (Ativo Circulante)_________________110.000,00 C: Ações em Tesouraria (Patrimônio Líquido)__________100.000,00 C:Receitas Financeiras (Receita Operacional)___________10.000,00\"],\"g\":1},{\"_id\":11,\"t\":\"Patrimônio Líquido\",\"b\":\"CESGRANRIO\",\"src\":\"PETROBRÁS/Técnico em Contabilidade/CESGRANRIO\",\"d\":\"Média\",\"tipo\":\"mc\",\"anulada\":false,\"e\":\"As reservas estatutárias são constituídas, por determinação do estatuto de uma companhia, para a destinação de uma parcela dos lucros do exercício. Para cada reserva estatutária, a empresa terá de estabelecer os seguintes critérios em seu estatuto:\",\"c\":\"segundo o Cosif, as reservas estatutárias devem estar previstas no Estatuto e ser constituídas pela destinação de uma parcela dos lucros do período, observando-se que: a) para cada reserva da espécie, devem ser definidos no Estatuto: I - de modo preciso e completo, a sua finalidade; II - os critérios para determinar a parcela do lucro líquido do período destinada à sua constituição; III - o limite máximo da reserva; b) as reservas estatutárias são utilizadas: I - nas finalidades previstas; Carlos Roberto Correa Aula 08 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br II - para compensar prejuízos, quando esgotados os lucros acumulados; III - para aumentar o capital social.\",\"o\":[\"definir sua finalidade de modo preciso e completo; fixar os critérios para determinar a parcela anual do lucro líquido a ser utilizada; e estabelecer seu limite máximo;\",\"definir a parcela dos prejuízos a serem absorvidos; evidenciar as contas que serão utilizadas para efetivar as reservas; e segregar os valores que serão aplicados em reservas dos dividendos propostos;\",\"definir a finalidade de cada reserva; evidenciar as parcelas de lucros a serem absorvidas; estabelecer seu limite máximo; e determinar a forma de reversão;\",\"definir as parcelas de lucros a serem absorvidas; fixar os limites de utilização; e estabelecer a forma de reversão;\",\"determinar os critérios para o estabelecimento das reservas; avaliar os resultados do exercício que devem ser absorvidos; fixar os limites de utilização; e estabelecer a forma de reversão.\"],\"g\":0},{\"_id\":12,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os saldos para as reservas de contingências, de incentivos fiscais e de lucros a realizar poderão ultrapassar o capital social.\",\"c\":\"o saldo das reservas de lucros, exceto as para contingências, de incentivos fiscais e de lucros a realizar , não poderá ultrapassar o capital social. Por conseguinte, os saldos para as reservas de contingências, de incentivos fiscais e de lucros a realizar poderão ultrapassar o capital social.\",\"g\":\"C\"},{\"_id\":13,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O principal objetivo das demonstrações financeiras preconizadas no Cosif é fornecer informações que representam uma síntese de normas e procedimentos contábeis para garantir uniformidade na obtenção e divulgação de informações econômico-financeiras atualizadas.\",\"c\":\"a questão define bem o objetivo das demonstrações financeiras.\",\"g\":\"C\"},{\"_id\":14,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instituições financeiras com patrimônio líquido inferior a R$2.000.000,00 estão dispensadas da elaboração e divulgação da Demonstração dos Fluxos de Caixa.\",\"c\":\"Instituições financeiras com patrimônio líquido inferior a R$2.000.000,00 na data-base de 31 de dezembro estão dispensadas da elaboração e divulgação da Demonstração dos Fluxos de Caixa.\",\"g\":\"C\"},{\"_id\":15,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Todas as instituições financeiras, independentemente do seu tamanho, devem preparar demonstrações financeiras anuais consolidadas adotando o padrão contábil internacional.\",\"c\":\"Apenas as instituições financeiras e demais instituições autorizadas a funcionar pelo Banco Central do Brasil registradas como companhia aberta ou líderes de conglomerado prudencial enquadrado nos Segmentos S1, S2 ou S3 devem elaborar demonstrações financeiras anuais consolidadas adotando o padrão contábil internacional. Carlos Roberto Correa Aula 08 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"E\"},{\"_id\":16,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A instituição que divulgar novamente suas demonstrações financeiras com alterações deve informar apenas em notas explicativas os motivos para essa nova divulgação.\",\"c\":\"o motivo das alterações em demonstrações financeiras devem ser divulgadas em notas explicativas.\",\"g\":\"C\"},{\"_id\":17,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A técnica de consolidação operacional em um conglomerado prudencial representa várias instituições como uma única entidade para apurar informações contábeis.\",\"c\":\"a consolidação operacional é usada para tratar informações contábeis de múltiplas instituições como se fosse apenas uma. Certíssimo!\",\"g\":\"C\"},{\"_id\":18,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Um conglomerado prudencial pode incluir tanto entidades financeiras quanto não financeiras.\",\"c\":\"Um conglomerado prudencial inclui tanto entidades financeiras quanto não financeiras, diferenciando-se do conglomerado financeiro que inclui apenas as financeiras.\",\"g\":\"E\"},{\"_id\":19,\"t\":\"Patrimônio Líquido\",\"b\":\"Autoral\",\"src\":\"Questão autoral · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A CVM tem a autoridade de redefinir a instituição líder de um conglomerado prudencial se considerar que a definição anterior foi inadequada.\",\"c\":\"O Banco Central tem a autoridade de redefinir a instituição líder de um conglomerado prudencial se considerar que a definição anterior foi inadequada.\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]},"Contabilidade de Instituições Financeiras (COSIF)::Aula 09":{"questoesPdf":[{"title":"Questões Extraídas — Simulado (Revisão Geral) · Aula 09 (42 itens)","content":"<!DOCTYPE html>\n<html lang=\"pt-BR\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>COSIF Aula 09 — Simulado</title>\n<style>\n  :root{\n    --brand:#0d3b66; --brand2:#1d4e89; --ink:#1e293b; --muted:#64748b;\n    --line:#e2e8f0; --card:#fff; --bg:#eef2f7; --soft:#f8fafc;\n    --green:#2e7d32; --green-bg:#e6f4ea; --red:#c0392b; --red-bg:#fdecea;\n    --yellow-bg:#fff7d6; --yellow-line:#b7791f; --blue-bg:#e8f0fb;\n    --hero1:#0d3b66; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(15,23,42,.10); --shadow-sm:0 3px 10px rgba(15,23,42,.04);\n    --badge-ce-bg:#ede9fe; --badge-ce:#6b3fa0; --badge-mc-bg:#e0f2f1; --badge-mc:#00695c;\n    --btn-re-bg:#e2e8f0; --btn-re-hover:#cbd5e1; --track:#e2e8f0;\n  }\n  html[data-theme=\"dark\"]{\n    --brand:#4f8cff; --brand2:#7aa7ff; --ink:#e8edf7; --muted:#9fb0cc;\n    --line:#2a3550; --card:#171e2e; --bg:#0f1420; --soft:#1d2740;\n    --green:#38d39f; --green-bg:#0f2e22; --red:#ff6b7a; --red-bg:#361318;\n    --yellow-bg:#2a2410; --yellow-line:#ffcc45; --blue-bg:#16264a;\n    --hero1:#0c1b3a; --hero2:#1d4e89; --hero-txt:#fff; --hero-sub:#c7d6ea;\n    --shadow:0 6px 18px rgba(0,0,0,.35); --shadow-sm:0 3px 10px rgba(0,0,0,.25);\n    --badge-ce-bg:#2a1f45; --badge-ce:#c4b5fd; --badge-mc-bg:#0f3330; --badge-mc:#5eead4;\n    --btn-re-bg:#243049; --btn-re-hover:#2e3d5c; --track:#22304a;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;font-family:\"Segoe UI\",-apple-system,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55;transition:background .25s,color .25s;}\n  .wrap{max-width:900px;margin:0 auto;padding:0 16px 90px;}\n  header.hero{background:linear-gradient(135deg,var(--hero1),var(--hero2));color:var(--hero-txt);padding:26px 20px;border-radius:0 0 18px 18px;position:relative;}\n  .kicker{display:inline-block;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:4px 11px;border-radius:999px;font-size:.75rem;font-weight:600;letter-spacing:.5px;}\n  header.hero h1{margin:12px 0 4px;font-size:1.7rem;}\n  header.hero p{margin:0;color:var(--hero-sub);font-size:.9rem;}\n  .theme-btn{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);color:#fff;padding:7px 12px;border-radius:999px;font-size:.78rem;font-weight:600;cursor:pointer;transition:.15s;}\n  .theme-btn:hover{background:rgba(255,255,255,.28);}\n  .scoreboard{position:sticky;top:0;z-index:50;background:var(--card);border:1px solid var(--line);border-radius:12px;margin:14px 0;padding:10px 12px;box-shadow:var(--shadow);display:flex;flex-wrap:wrap;gap:8px;align-items:center;}\n  .stat{flex:1;min-width:78px;text-align:center;padding:6px 4px;border-radius:9px;background:var(--soft);}\n  .stat b{display:block;font-size:1.15rem;line-height:1.1;}\n  .stat span{font-size:.68rem;text-transform:uppercase;letter-spacing:.4px;color:var(--muted);}\n  .stat.c b{color:var(--green);} .stat.e b{color:var(--red);} .stat.p b{color:var(--brand2);}\n  .sb-actions{display:flex;gap:6px;width:100%;justify-content:flex-end;}\n  button{cursor:pointer;font-family:inherit;border:none;border-radius:9px;font-weight:600;transition:.15s;}\n  .btn-an{background:var(--brand);color:#fff;padding:9px 16px;font-size:.85rem;}\n  .btn-re{background:var(--btn-re-bg);color:var(--ink);padding:9px 14px;font-size:.85rem;}\n  .btn-an:hover{filter:brightness(1.12);} .btn-re:hover{background:var(--btn-re-hover);}\n  .progress{height:6px;background:var(--track);border-radius:99px;width:100%;overflow:hidden;margin-top:4px;}\n  .progress>div{height:100%;background:linear-gradient(90deg,var(--green),var(--brand2));width:0;transition:.3s;}\n  .filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;}\n  .filters button{background:var(--card);border:1px solid var(--line);color:var(--brand2);padding:5px 11px;font-size:.78rem;}\n  .filters button.active{background:var(--brand);color:#fff;border-color:var(--brand);}\n  .hint{font-size:.8rem;color:var(--muted);text-align:center;margin:8px 0;}\n  .q{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:12px 0;box-shadow:var(--shadow-sm);}\n  .q-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;}\n  .q-num{font-weight:700;color:var(--brand2);font-size:.9rem;}\n  .badges{display:flex;gap:5px;flex-wrap:wrap;}\n  .badge{font-size:.66rem;text-transform:uppercase;letter-spacing:.4px;padding:3px 8px;border-radius:6px;font-weight:700;}\n  .badge.banca{background:var(--blue-bg);color:var(--brand2);border:1px solid var(--line);}\n  .badge.tema{background:var(--soft);color:var(--muted);}\n  .badge.ce{background:var(--badge-ce-bg);color:var(--badge-ce);}\n  .badge.mc{background:var(--badge-mc-bg);color:var(--badge-mc);}\n  .badge.dif-facil{background:var(--green-bg);color:var(--green);}\n  .badge.dif-media{background:var(--yellow-bg);color:var(--yellow-line);}\n  .badge.dif-dificil{background:var(--red-bg);color:var(--red);}\n  .enun{margin:8px 0 12px;font-size:.97rem;}\n  .opts{display:flex;flex-direction:column;gap:8px;}\n  .opt{border:1.5px solid var(--line);border-radius:9px;padding:10px 13px;font-size:.9rem;cursor:pointer;background:var(--card);color:var(--ink);text-align:left;display:flex;gap:9px;align-items:flex-start;}\n  .opt:hover{border-color:var(--brand2);background:var(--soft);}\n  .opt .k{font-weight:700;color:var(--brand2);flex:none;}\n  .opt.sel{border-color:var(--brand);background:var(--blue-bg);}\n  .opt.correct{border-color:var(--green);background:var(--green-bg);}\n  .opt.wrong{border-color:var(--red);background:var(--red-bg);}\n  .comment{margin-top:11px;border-radius:9px;padding:11px 13px;font-size:.87rem;display:none;border-left:5px solid;}\n  .comment.show{display:block;}\n  .qimg{max-width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}\n  .enun .qimg{margin:2px 0 4px;}\n  .comment.ok{background:var(--green-bg);border-color:var(--green);}\n  .comment.no{background:var(--red-bg);border-color:var(--red);}\n  .comment .res{font-weight:700;display:block;margin-bottom:3px;}\n  .comment.ok .res{color:var(--green);} .comment.no .res{color:var(--red);}\n  #analysis{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px;margin:16px 0;box-shadow:var(--shadow);}\n  #analysis.show{display:block;}\n  #analysis h2{color:var(--brand2);margin:0 0 14px;}\n  #analysis h3{color:var(--brand2);}\n  .big{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n  .big .box{flex:1;min-width:110px;background:var(--soft);border-radius:12px;padding:14px;text-align:center;}\n  .big .box b{display:block;font-size:1.9rem;color:var(--brand2);}\n  .big .box.gc b{color:var(--green);} .big .box.ge b{color:var(--red);}\n  .big .box span{font-size:.72rem;text-transform:uppercase;color:var(--muted);letter-spacing:.4px;}\n  .tbar{margin:9px 0;}\n  .tbar .tl{display:flex;justify-content:space-between;font-size:.84rem;margin-bottom:3px;}\n  .tbar .track{height:12px;background:var(--track);border-radius:99px;overflow:hidden;}\n  .tbar .fill{height:100%;border-radius:99px;transition:.5s;}\n  .verdict{padding:8px 10px;border-radius:8px;font-size:.82rem;margin-top:4px;}\n  .v-forte{background:var(--green-bg);color:var(--green);}\n  .v-medio{background:var(--yellow-bg);color:var(--yellow-line);}\n  .v-fraco{background:var(--red-bg);color:var(--red);}\n  .rec{margin-top:16px;background:var(--yellow-bg);border-left:5px solid var(--yellow-line);border-radius:9px;padding:12px 14px;font-size:.87rem;}\n  .rec b{color:var(--yellow-line);}\n  footer{text-align:center;color:var(--muted);font-size:.8rem;margin-top:24px;}\n\n  .qfig{margin:0 0 12px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:10px;text-align:center;}\n  .qfig svg{max-width:100%;height:auto;}\n  .qfig table{width:100%;border-collapse:collapse;font-size:.82rem;margin:0;}\n  .qfig th,.qfig td{border:1px solid var(--line);padding:5px 7px;text-align:center;}\n  .qfig th{background:var(--card);color:var(--brand2);}\n  .badge.figb{background:var(--yellow-bg);color:var(--yellow-line);}\n\n.qfig{margin:0 0 14px;padding:14px;background:var(--bg,#f3f5fb);border:1px solid var(--line,#e2e6f0);border-radius:12px;text-align:center;}\n.qfig img{max-width:min(100%,480px);height:auto;border-radius:8px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.12);}\n.qfig .cap{margin-top:8px;font-size:12px;color:var(--muted,#7a879e);font-style:italic;}\n.badge.figb{background:#2563eb;color:#fff;}\n\n.prof-label,.meu-label{display:inline-block;font-size:.6rem;letter-spacing:.6px;text-transform:uppercase;font-weight:800;padding:3px 8px;border-radius:5px;margin:2px 0 8px;}\n.prof-label{background:rgba(100,116,139,.16);color:var(--muted);}\n.comment .body{font-size:.9rem;line-height:1.6;}\n.comment .body p{margin:0 0 9px;}\n.comment .body p:last-child{margin-bottom:0;}\n.comment .body strong{color:var(--brand);font-weight:700;}\n.comment.ok .body strong{color:var(--green);} .comment.no .body strong{color:var(--red);}\n.compl{margin-top:12px;background:var(--blue-bg);border:1px solid var(--brand2);border-left:5px solid var(--brand2);border-radius:9px;padding:11px 13px;}\n.meu-label{background:var(--brand2);color:#fff;}\n.compl .body{font-size:.88rem;line-height:1.6;color:var(--ink);}\n.compl .body strong{color:var(--brand);font-weight:700;}\n.katex{font-size:1.02em;}\n.comment .body .kf{display:block;margin:7px 0;overflow-x:auto;}\n.figc{margin:14px auto;text-align:center;}\n.figc img{max-width:100%;height:auto;border-radius:6px;}\n.q .body .emb,.comment .emb{color:var(--brand);font-weight:700}.q .body .emk,.comment .emk{font-weight:700;color:#1a1a1a}.q .body .emr,.comment .emr{color:var(--red);font-weight:700}.q .body .emu,.comment .emu{text-decoration:underline}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.css\">\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js\"></script>\n<script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js\"></script>\n</head>\n<body>\n<div class=\"wrap\">\n<header class=\"hero\">\n  <button class=\"theme-btn\" id=\"themeToggle\">🌙 Escuro</button>\n  <span class=\"kicker\">COSIF · AULA 09 · QUESTÕES AULA</span>\n  <h1>Questões Aula — extraídas do PDF</h1>\n  <p>Contabilidade de Instituições Financeiras (COSIF) · Aula 09 — <b>Simulado — Revisão Geral do COSIF</b> · itens <b>certo/errado</b> e <b>múltipla escolha</b> · <span id=\"qtot\"></span> questões</p>\n</header>\n\n<div class=\"scoreboard\">\n  <div class=\"stat p\"><b id=\"s-resp\">0</b><span>Respondidas</span></div>\n  <div class=\"stat c\"><b id=\"s-cert\">0</b><span>Certas</span></div>\n  <div class=\"stat e\"><b id=\"s-err\">0</b><span>Erradas</span></div>\n  <div class=\"stat p\"><b id=\"s-perc\">0%</b><span>Aproveitamento</span></div>\n  <div class=\"progress\"><div id=\"s-prog\"></div></div>\n  <div class=\"sb-actions\">\n    <button class=\"btn-re\" onclick=\"reiniciar()\">↺ Reiniciar</button>\n    <button class=\"btn-an\" onclick=\"verAnalise()\">📊 Ver Análise</button>\n  </div>\n</div>\n\n<div class=\"filters\" id=\"filters\"></div>\n<p class=\"hint\">Marque sua resposta em cada item — o gabarito e o comentário aparecem na hora. Ao final, clique em Ver Análise.</p>\n\n<div id=\"analysis\"></div>\n<div id=\"quiz\"></div>\n\n<footer>Contabilidade de Instituições Financeiras (COSIF) · Aula 09 — questões extraídas do PDF (Prof. Carlos Roberto Correa · Estratégia)</footer>\n</div>\n\n<script>\nconst Q = [{\"_id\":0,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As normas e procedimentos, bem como as demonstrações financeiras padronizadas previstas no Plano Contábil das Instituições do Sistema Financeiro Nacional - Cosif, não são de uso obrigatório para as agências de fomento mercantil.\",\"c\":\"Não podemos confundir as agências de fomento mercantil com as sociedades de fomento mercantil (factorings). Conforme vimos, as sociedades de fomento mercantil não estão sujeitas às normas do Banco Central, mas as agências de fomento estão. Não Confundir!\",\"g\":\"E\"},{\"_id\":1,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O aumento de Capital Social com a utilização de Reservas de Capital resulta em um fato permutativo com impacto a débito na conta “Reservas de Capital” e a créd ito na conta “Capital Social”.\",\"c\":\"A questão está perfeita. Vejamos o lançamento contábil: Conta Cosif Lançamento 6.1.3.00.00-0 D – Reservas de Capital 6.1.1.00.00-4 C – Capital Social\",\"g\":\"C\"},{\"_id\":2,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As diretrizes consubstanciadas no Cosif, bem como a existência de títulos contábeis, pressupõem permissão para prática de operações ou serviços que dependam de prévia autorização do Banco Central.\",\"c\":\"Sendo o Cosif um conjunto integrado de normas, procedimentos e critérios de escrituração contábil de forma genérica, as diretrizes nele consubstanciadas, bem como a existência de títulos contábeis, não pressupõem permissão para prática de operações ou serviços vedados por lei, regulamento ou ato administrativo, ou dependente de prévia autorização do Banco Central.\",\"g\":\"E\"},{\"_id\":3,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As instituições financeiras devem apurar os resultados em períodos fixos de tempo, observando, obrigatoriamente, o período de 1º de janeiro a 31 de dezembro. Facultativamente, as instituições financeiras poderão apurar os resultados semestralmente.\",\"c\":\"Esses resultados são apurados semestralmente (1º de janeiro a 30 de junho e 1º de julho a 31 de dezembro).\",\"g\":\"E\"},{\"_id\":4,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"No encerramento do exercício social, os lucros não destinados nos termos da regulamentação em vigor deverão ser distribuídos, sendo que a conta de lucros ou prejuízos acumulados não deverá apresentar saldo positivo.\",\"c\":\"Conforme orientações trazidas pela Resolução 3.605/2008: “Art. 5º, no encerramento do exercício social, os lucros não destinados nos termos da regulamentação em vigor deverão ser distribuídos, sendo que a conta de lucros ou prejuízos acumulados não deverá apresentar saldo positivo .” Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"C\"},{\"_id\":5,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As operações ativas e passivas contratadas com rendas e encargos prefixados contabilizam- se pelo do principal, registrando-se as rendas e os encargos a apropriar em subtítulo de uso interno do próprio título ou subtítulo contábil utilizado para registrar a operação. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"As operações ativas e passivas contratadas com rendas e encargos prefixados contabilizam-se pelo valor presente , registrando-se as rendas e os encargos a apropriar em subtítulo de uso interno do próprio título ou subtítulo contábil utilizado para registrar a operação.\",\"g\":\"E\"},{\"_id\":6,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As operações ativas e passivas contratadas com rendas e encargos pós-fixados ou flutuantes contabilizam-se pelo valor do principal, a débito ou a crédito das contas que as registram. Essas mesmas contas acolhem os juros e os ajustes mensais decorrentes das variações da unidade de correção ou dos encargos contratados, no caso de taxas flutuantes.\",\"c\":\"É exatamente isso. Literalidade do Cosif.\",\"g\":\"C\"},{\"_id\":7,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A rentabilidade a partir da curva do papel expressa o ganho obtido se o título for mantido até o seu vencimento. O termo curva do papel surge porque o preço do título ao longo do tempo apresenta uma trajetória curva que converge para o valor de resgate no vencimento.\",\"c\":\"A Curva do Papel reflete a valorização de um título ao longo do tempo, do instante da compra até seu vencimento, refletindo o RENDIMENTO do título. Lembram-se do exemplo que vimos em aula?\",\"g\":\"C\"},{\"_id\":8,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Na categoria “Títulos mantidos até o vencimento”, devem ser registrados os títulos e valores mobiliários, exceto ações não resgatáveis, para os quais haja intenção e capacidade financeira da instituição de mantê-los em carteira até o vencimento.\",\"c\":\"Literalidade da classificação dada pela Circular 3.068/2001.\",\"g\":\"C\"},{\"_id\":9,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Títulos para negociação - devem ser registrados os títulos e valores mobiliários que não se enquadrem nas categorias “títulos disponíveis para venda” e “títulos mantidos até o vencimento”.\",\"c\":\"Títulos para negociação - devem ser registrados os títulos e valores mobiliários adquiridos com o propósito de serem ativa e frequentemente negociados.\",\"g\":\"E\"},{\"_id\":10,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Título para negociação é marcado a mercado. O “Ajuste a Valor de Mercado” ajusta a conta que registra o título no ativo (Cosif 1.3) em contrapartida à conta de receita (Cosif 8), quando for valorização, ou em contrapartida à conta de despesa (Cosif 7), quando for desvalorização.\",\"c\":\"Questão maldosa. O grupo das receitas é o 7 e o das despesas é o 8. Percebam que a questão inverteu os grupos. “Título para negociação é marcado a mercado. O “Ajuste a Valor de Mercado” ajusta a conta que registra o título no ativo (Cosif 1.3) em contrapartida à conta de receita (Cosif 7) , quando for valorização, ou em contrapartida à conta de despesa (Cosif 8) , quando for desvalorização.\",\"g\":\"E\"},{\"_id\":11,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Título mantido até o vencimento não é marcado a mercado. Os rendimentos são contabilizados na conta que registra o título no ativo (Cosif 1.3) em contrapartida à conta de receitas (Cosif 7).\",\"c\":\"Perfeito! É exatamente isso que o Cosif nos diz. Se não há a intenção de resgatá-lo antecipadamente, não há que se falar em marcação a mercado para os títulos mantidos até o vencimento. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"C\"},{\"_id\":12,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Na hipótese de transferência de títulos disponíveis para venda, os ganhos e perdas realizados, registrados como componente destacado do patrimônio líquido, devem ser reconhecidos no resultado do período imediatamente.\",\"c\":\"Na hipótese de transferência de títulos disponíveis para venda, os ganhos e perdas realizados, registrados como componente destacado do patrimônio líquido, devem ser reconhecidos no resultado do período imediatamente, quando para a categoria títulos para negociação .\",\"g\":\"E\"},{\"_id\":13,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O caráter está atrelado à capacidade do requerente de ressarcir o crédito pleiteado, tendo em vista sua renda (salário, subsídio, etc.). No caso de empresas, por exemplo, são analisadas as demonstrações financeiras, com particular ênfase na liquidez, nos fluxos e projeções de caixa, etc. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"A questão se refere aos 5Cs do crédito. O caráter está atrelado à índole do tomador do empréstimo e sua predisposição em pagar a operação de crédito contratada. A explicação da questão se refere à capacidade do tomador.\",\"g\":\"E\"},{\"_id\":14,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Financiamentos são as operações de crédito realizadas com destinação específica, vinculadas à comprovação da aplicação dos recursos.\",\"c\":\"É isso! Lembrem-se desse detalhe na sua prova: financiamento – destinação específica; empréstimo: sem destinação específica.\",\"g\":\"C\"},{\"_id\":15,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Empréstimos são as operações de crédito realizadas sem destinação específica ou vínculo à comprovação da aplicação dos recursos.\",\"c\":\"Idem\",\"g\":\"C\"},{\"_id\":16,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Ao classificar o risco da carteira de crédito de um cliente, o menor risco que o analista de rating poderá atribuir é o risco “A”.\",\"c\":\"As instituições financeiras e demais instituições autorizadas a funcionar pelo BACEN devem classificar as operações de crédito, em ordem crescente de risco, nos seguintes níveis: nível AA ; nível A; nível B; nível C; nível D; nível E; nível F; nível G; e nível H.\",\"g\":\"E\"},{\"_id\":17,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A classificação da operação no nível de risco adequado é responsabilidade da empresa de auditoria externa contratada pela instituição financeira, de forma a preservar a imparcialidade no ato de atribuir riscos às operações.\",\"c\":\"A classificação da operação no nível de risco adequado é responsabilidade da instituição financeira detentora do crédito.\",\"g\":\"E\"},{\"_id\":18,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Admite-se, excepcionalmente, classificação diversa em relação ao maior risco para cliente ou grupo econômico do qual faça parte, observando, em relação à operação, características das garantias, particularmente quanto à suficiência e liquidez.\",\"c\":\"Essa é uma das exceções para se admitir classificação diversa em relação à de maior risco. Vamos relembrar as exceções: • Natureza e finalidade da transação; • Características das garantias, particularmente quanto à suficiência e liquidez; e • O valor.\",\"g\":\"C\"},{\"_id\":19,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A provisão para créditos de liquidação duvidosa deve ser constituída sobre o valor contábil dos créditos mediante registro a débito de DESPESAS DE PROVISOES OPERACIONAIS e a crédito da adequada conta de provisão para operações de crédito.\",\"c\":\"Esse é o lançamento clássico de uma provisão. Lembrando que conta de PCLD é retificadora do ativo.\",\"g\":\"C\"},{\"_id\":20,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Instrumentos financeiros derivativos são aqueles cujo valor varia em decorrência de mudanças em taxa de juros, preço de título ou valor mobiliário, preço de mercadoria, taxa de câmbio, índice de bolsa de valores, índice de preço, índice ou classificação de crédito, ou qualquer outra variável similar específica cujo investimento inicial seja inexistente ou pequeno em relação ao valor do contrato, e que sejam liquidados em data futura.\",\"c\":\"Definição perfeita de instrumento financeiro derivativo.\",\"g\":\"C\"},{\"_id\":21,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os hedgers são agentes econômicos que desejam se proteger dos riscos derivados das flutuações adversas nos preços de commodities , taxas de juros, moedas estrangeiras ou ações. O hedger busca tirar proveito de situações econômicas para obter lucro.\",\"c\":\"O objetivo do Hedge não é obter lucros, mas sim travar o preço e buscar proteção. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br ==2ad7be==\",\"g\":\"E\"},{\"_id\":22,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O ajuste diário, presente nos contratos a termo, é a liquidação diária do que foi negociado. Diariamente as operações em aberto nas Bolsas são ajustadas a mercado. Isso equivale a atualizar diariamente o valor das operações, fazendo encerramentos e recontratações todos os dias durante a vigência do contrato. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"O ajuste diário é uma característica dos contratos futuros.\",\"g\":\"E\"},{\"_id\":23,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Haja vista que nos contratos futuros existe o ajuste diário, o máximo de prejuízo que um agente pode gerar no mercado é aquele provocado pela variação de preços de um único dia. Sendo assim, o risco de crédito de um contrato futuro passa a ser baixo, pois haverá acerto todos os dias.\",\"c\":\"Perfeito. Como há ajuste diário, o máximo de prejuízo é aquele apurado dentro de um único dia, o que caracteriza risco de crédito baixo.\",\"g\":\"C\"},{\"_id\":24,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A condição para o exercício de uma opção de venda é que o preço à vista seja inferior ao preço de exercício.\",\"c\":\"Vamos relembrar as condições das opções? Condição para o Exercício de uma Opção de Venda: Preço à Vista < Preço de Exercício Condição para o Titular obter Lucro com Opção Venda: Preço à Vista < Preço de Exercício – Prêmio\",\"g\":\"C\"},{\"_id\":25,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Um arrendamento mercantil deve ser classificado como operacional se ele transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade.\",\"c\":\"Um arrendamento mercantil deve ser classificado como financeiro se ele transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade. Um arrendamento mercantil deve ser classificado como operacional se ele não transferir substancialmente todos os riscos e/ou benefícios inerentes à propriedade.\",\"g\":\"E\"},{\"_id\":26,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Para corrigir a distorção no patrimônio em uma operação de arrendamento mercantil, o Cosif determina que seja feito um ajuste, confrontando-se o valor contábil do contrato com o valor presente dos fluxos de pagamentos futuros (descontado pela TIR). Esse ajuste tem o objetivo de demonstrar o resultado contábil da operação de leasing financeiro como se essa operação fosse contabilizada como financiamento.\",\"c\":\"Isso mesmo! Esse é o ajuste que o Cosif determina que as instituições façam para estarem alinhadas com as normas internacionais de contabilidade.\",\"g\":\"C\"},{\"_id\":27,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Depósitos à vista (ou depósitos em conta corrente como são mais popularmente conhecidos) são a captação de recursos junto ao público em geral (pessoas físicas e jurídicas de direito público e privado). Dentre as suas principais características, destacamos o fato de não serem remunerados e de permanecerem no banco por prazo indeterminado, dependendo do fluxo de caixa da instituição financeira para serem movimentados.\",\"c\":\"Uma das características dos depósitos à vista é a livre movimentação. Não tem essa de depender do fluxo de caixa da instituição financeira.\",\"g\":\"E\"},{\"_id\":28,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Os depósitos à vista têm como característica o fato de não serem remunerados. Contudo, para ganhar mercado e atrair clientes, a instituição financeira poderá oferecer condições mais vantajosas em seus depósitos à vista e oferecer a bonificação em juros sobre o valor efetivamente depositado.\",\"c\":\"É vedada a bonificação de juros, a qualquer título, sobre depósitos à vista, sendo passíveis de penalidades os bancos que não observarem essa determinação!\",\"g\":\"E\"},{\"_id\":29,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"LCIs são títulos criados com o objetivo de estimular o crédito imobiliário, uma vez que sua captação implica o necessário direcionamento dos recursos para essa atividade. Normalmente, os bancos utilizam esse funding para conceder crédito a empresas do segmento de construção (construtoras e incorporadoras).\",\"c\":\"É exatamente essa a função da LCI: servir de funding para que as instituições financeiras possam conceder créditos a empresas do segmento de construção.\",\"g\":\"C\"},{\"_id\":30,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"A emissão de debêntures não é admitida para as instituições financeiras, incluindo as sociedades de arrendamento mercantil. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"A emissão de debêntures não é admitida para as instituições financeiras. Exceção: sociedades de arrendamento mercantil. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"E\"},{\"_id\":31,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"O aumento de capital social, deliberado em assembleia de acionistas ou reunião de quotistas, deve ser registrado, enquanto não aprovado pelo Banco Central, em AUMENTO DE CAPITAL, tendo como contrapartida CAPITAL A REALIZAR, quando realizado com recursos de acionistas ou quotistas.\",\"c\":\"Literalidade do Cosif. Vejamos o lançamento descrito na questão: Natureza Código/Conta Título Contábil D 6.1.1.50.00-9 Capital a Realizar C 6.1.1.10.00-1 Capital\",\"g\":\"C\"},{\"_id\":32,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"As instituições não podem receber recursos de acionistas ou quotistas, destinados a aumento do capital social, antes da realização de assembleia de acionistas ou reunião de quotistas que delibere o aumento do capital social.\",\"c\":\"Literalidade do Cosif.\",\"g\":\"C\"},{\"_id\":33,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Para o Cosif, são “Coligadas” as sociedades em que uma participa do capital da outra com 20% (dez por cento) ou mais, sem controlá-la.\",\"c\":\"O percentual para ser coligada é de 10% , pessoal.\",\"g\":\"E\"},{\"_id\":34,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Devem ser avaliados pelo método da equivalência patrimonial os investimentos em coligadas, quando participarem com 20% (vinte por cento) ou mais do capital votante ou detiverem influência significativa em sua administração.\",\"c\":\"Literalidade do Cosif. Lembremos, 10% do capital sem o controle é coligada. Quanto ao método de avaliação do investimento, se for controlada ou se a instituição tiver mais de 20% do capital votante ou, ainda, influência significativa em sua administração, o investimento na coligada será avaliado pelo MEP.\",\"g\":\"C\"},{\"_id\":35,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Se uma instituição autorizada a funcionar pelo BACEN controla outra instituição que possui participação societária na controladora, as participações recíprocas e eventuais dividendos declarados entre ambas devem ser eliminados para a obtenção do balanço patrimonial consolidado.\",\"c\":\"Nas participações recíprocas, deve ocorrer a eliminação do valor do investimento de uma instituição contra a correspondente participação acionária no PL da outra, observada a existência de dividendos declarados entre ambas, os quais devem ser eliminados.\",\"g\":\"C\"},{\"_id\":36,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Todas as instituições financeiras fiscalizadas e supervisionadas pelo Banco Central do Brasil devem submeter à auditoria independente suas demonstrações financeiras, inclusive as notas explicativas.\",\"c\":\"Às sociedades de crédito ao microempreendedor (SCM) não se aplica a obrigatoriedade de submeter suas demonstrações financeiras, inclusive as notas explicativas, à auditoria independente.\",\"g\":\"E\"},{\"_id\":37,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Para fins de registro contábil, considera-se instrumento financeiro todos os contratos que dão origem a um ativo financeiro para uma entidade e a um passivo financeiro ou instrumento de capital próprio para outra.\",\"c\":\"Segundo a Resolução 3.534/2008, para fins de registro contábil, considera-se instrumento financeiro qualquer contrato que dê origem a um ativo financeiro para uma entidade e a um passivo financeiro ou instrumento de capital próprio para outra.\",\"g\":\"C\"},{\"_id\":38,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Valor justo é quantia pela qual um ativo pode ser negociado ou um passivo liquidado, entre partes informadas, não relacionadas e em condições de equilíbrio.\",\"c\":\"Essa é a definição de valor justo da Resolução 3.534/2008.\",\"g\":\"C\"},{\"_id\":39,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Na categoria operações com transferência substancial dos riscos e benefícios devem ser classificadas as operações em que o vendedor ou cedente transfere substancialmente todos os riscos e benefícios de propriedade do ativo financeiro objeto da operação. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"É exatamente isso. Muito cuidado com a palavra “todos”, mas é assim que a resolução 3.533/2008 define as operações com transferência substancial dos riscos e benefícios.\",\"g\":\"C\"},{\"_id\":40,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Presume-se que os riscos e benefícios do ativo financeiro foram retidos pelo vendedor ou cedente quando o valor da garantia prestada, por qualquer forma, para compensação de perdas de crédito, for superior à perda provável ou ainda quando o valor das cotas subordinadas de FIDC adquiridas for superior à perda provável.\",\"c\":\"Se o valor da garantia prestada for maior que o risco assumido (cotas subordinadas de FIDC), presume-se que os riscos e benefícios foram retidos. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"C\"},{\"_id\":41,\"t\":\"Simulado\",\"b\":\"Simulado\",\"src\":\"Simulado COSIF · Prof. Carlos Roberto Correa\",\"d\":\"Média\",\"tipo\":\"ce\",\"anulada\":false,\"e\":\"Fica caracterizada a retenção substancial dos riscos e benefícios quando o valor da garantia prestada, de qualquer forma, para compensação de perdas de crédito, ou quando o valor das cotas subordinadas de Fundo de Investimento em Direitos Creditórios (FDIC) adquiridas, for superior à perda média histórica do ativo financeiro objeto da operação de venda ou de transferência, ajustada para as condições correntes da economia, acrescida de três desvios-padrões. 1. ERRADO. Os capítulos do Cosif estão hierarquizados na ordem de apresentação . Assim, nas dúvidas de interpretação entre as Normas Básicas e Elenco de Contas, prevalecem as Normas Básicas . A questão citou princípios básicos! Cuidado para não confundir princípios com normas. 2. ERRADO. Vamos relembrar o que o Cosif nos diz sobre seus objetivos: As normas consubstanciadas neste Plano Contábil têm por objetivo uniformizar os registros contábeis dos atos e fatos administrativos praticados, racionalizar a utilização de contas, estabelecer regras, critérios e procedimentos necessários à obtenção e divulgação de dados, possibilitar o acompanhamento do sistema financeiro, bem como a análise, a avaliação do desempenho e o controle, de modo que as demonstrações financeiras elaboradas expressem, com fidedignidade e clareza, a real situação econômico-financeira da instituição e conglomerados financeiros.” (Circular 1273/87) Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"c\":\"Essa foi maldosa! Fica caracterizada a retenção substancial dos riscos e benefícios quando o valor da garantia prestada, de qualquer forma, para compensação de perdas de crédito, ou quando o valor das cotas subordinadas de Fundo de Investimento em Direitos Creditórios (FDIC) adquiridas, for superior à perda média histórica do ativo financeiro objeto da operação de venda ou de transferência, ajustada para as condições correntes da economia, acrescida de dois desvios-padrões. Carlos Roberto Correa Aula 09 (Somente em PDF) BACEN (Analista - Área 2 - Economia e Finanças) Contabilidade de Instituições Financeiras Padrão COSIF www.estrategiaconcursos.com.br\",\"g\":\"E\"}];\n</script>\n<script>\nconst root=document.documentElement;\nconst THEME_KEY='bacen-quizaula-theme';\nfunction applyTheme(t){root.setAttribute('data-theme',t);const btn=document.getElementById('themeToggle');if(btn)btn.textContent=t==='dark'?'☀️ Claro':'🌙 Escuro';try{localStorage.setItem(THEME_KEY,t);}catch(e){}}\n(function(){let t='light';try{t=localStorage.getItem(THEME_KEY)||'light';}catch(e){}applyTheme(t);})();\ndocument.getElementById('themeToggle').onclick=()=>applyTheme(root.getAttribute('data-theme')==='dark'?'light':'dark');\n\n\nconst FIGS = {};\n\n\nfunction _esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nconst _TERMS=[/qualitativas?( nomina(l|is))?/gi,/qualitativas?( ordina(l|is))?/gi,/quantitativas?( discretas?)?/gi,/quantitativas?( cont[íi]nuas?)?/gi,/frequ[êe]ncia (absoluta|relativa|acumulada)/gi,/histograma/gi,/gr[áa]fico de (setores|barras|colunas|linha)/gi,/pol[íi]gono de frequ[êe]ncias?/gi,/s[ée]rie (temporal|cronol[óo]gica|geogr[áa]fica)/gi,/popula[çc][ãa]o(-alvo| referenciada)?/gi,/\\bamostra\\b/gi,/\\bcenso\\b/gi,/vari[áa]vel (discreta|cont[íi]nua|nominal|ordinal)/gi];\nfunction _bold(seg){ let s=seg; _TERMS.forEach(re=>{ s=s.replace(re,m=>'\\u0001'+m+'\\u0002'); }); return s.replace(/\\u0001/g,'<strong>').replace(/\\u0002/g,'</strong>'); }\n// formata preservando $...$ (math) intactos; negrito **x**; termos-chave; parágrafos\n/* figc: figure embedded in comment */\nfunction fmt(t){\n  if(!t) return '';\n  t=String(t).replace(/\\\\\\$/g,'\\u0003'); // protege \\$ (cifrão literal) do parser de math\n  t=t.replace(/R\\$/g,'R\\u0003'); // protege moeda \"R$\" (nunca é delimitador de math) — evita engolir texto\n  const parts=String(t).split(/(\\$\\$[^$]*\\$\\$|\\$[^$]*\\$)/g); // separa segmentos math ($$ display e $ inline)\n  let s=parts.map((p,i)=>{ if(i%2===1) return p; let e=_esc(p); e=e.replace(/([;:.])[ \\t]+((?:[a-z]|[ivx]{1,4}|\\d{1,2})\\))(?=\\s)/g,'$1\\n$2'); e=e.replace(/:[ \\t]+(?=(?:R?\\u0003\\s*)?[\\d(])/g,':\\n'); e=e.replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1</strong>'); e=e.replace(/\\*([^*]+?)\\*/g,'<em>$1</em>'); e=e.replace(/⟦b⟧/g,'<span class=\"emb\">').replace(/⟦k⟧/g,'<span class=\"emk\">').replace(/⟦r⟧/g,'<span class=\"emr\">').replace(/⟦u⟧/g,'<span class=\"emu\">').replace(/⟦i⟧/g,'<em>').replace(/⟦\\/i⟧/g,'</em>').replace(/⟦\\/[bkru]⟧/g,'</span>'); return _bold(e); }).join('');\n  s=s.split(/\\n{2,}/).map(p=>'<p>'+p.replace(/\\n/g,'<br>')+'</p>').join('');\n  s=s.replace(/\\u0003/g,'<span class=\"cur\">$</span>'); // restaura cifrão literal isolado (auto-render não o pareia como math)\n  s=s.replace(/<p>\\s*⟦IMG:([a-z0-9_]+)⟧\\s*<\\/p>/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  s=s.replace(/⟦IMG:([a-z0-9_]+)⟧/gi,(m,k)=>FIGS[k]?('<figure class=\"figc\">'+FIGS[k]+'</figure>'):'');\n  return s;\n}\nfunction renderMath(el){ if(window.renderMathInElement){ try{ renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}); }catch(e){} } else { setTimeout(()=>renderMath(el),150); } }\nwindow.addEventListener('load',()=>{const q=document.getElementById('quiz'); if(q) renderMath(q);});\nconst quiz=document.getElementById('quiz');\nlet ativo=\"TODOS\";\nQ.forEach((q,i)=>q._id=i);\ndocument.getElementById('qtot').textContent=Q.length;\nfunction norm(s){return (s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}\nfunction letter(i){return String.fromCharCode(65+i);}\nconst temas=[\"TODOS\",...[...new Set(Q.map(q=>q.t))]];\nconst fc=document.getElementById('filters');\ntemas.forEach(tm=>{\n  const b=document.createElement('button');\n  b.textContent=tm+(tm===\"TODOS\"?\" (\"+Q.length+\")\":\" (\"+Q.filter(x=>x.t===tm).length+\")\");\n  if(tm===\"TODOS\")b.classList.add('active');\n  b.onclick=()=>{ativo=tm;document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render();};\n  fc.appendChild(b);\n});\nconst state={};\nfunction render(){\n  quiz.innerHTML=\"\";\n  const lista=ativo===\"TODOS\"?Q:Q.filter(x=>x.t===ativo);\n  lista.forEach((q)=>{\n    const div=document.createElement('div');div.className=\"q\";div.id=\"q\"+q._id;\n    const st=state[q._id];\n    const badges=`<span class=\"badge banca\">${q.b}</span>\n      <span class=\"badge tema\">${q.t}</span>\n      <span class=\"badge ${q.tipo}\">${q.tipo==='ce'?'Certo/Errado':'Múltipla escolha'}</span>\n      <span class=\"badge dif-${norm(q.d)}\">${q.d}</span>${q.figs&&q.figs.length?'<span class=\"badge figb\">🖼 Figura</span>':''}`;\n    let body=\"\";\n    if(q.tipo==='ce'){\n      body=`<div class=\"opts\">\n        <button class=\"opt ${st&&st.pick==='C'?'sel':''}\" data-p=\"C\">C · Certo</button>\n        <button class=\"opt ${st&&st.pick==='E'?'sel':''}\" data-p=\"E\">E · Errado</button>\n      </div>`;\n    }else{\n      const nn=q.eImg?(q.nopts||5):q.o.length;\n      body=`<div class=\"opts\">`+Array.from({length:nn}).map((_,k)=>\n        `<button class=\"opt ${st&&st.pick===k?'sel':''}\" data-p=\"${k}\"><span class=\"k\">${letter(k)}</span>${q.eImg?'':q.o[k]}</button>`\n      ).join(\"\")+`</div>`;\n    }\n    div.innerHTML=`<div class=\"q-head\"><span class=\"q-num\">Q${q._id+1}</span><div class=\"badges\">${badges}</div></div>\n      <div class=\"enun\">${q.eImg?('<img class=\"qimg\" src=\"'+q.eImg+'\" alt=\"enunciado\">'):('<div class=\"body\">'+fmt(q.e)+'</div>')}</div>${body}\n      <div class=\"comment\"></div>`;\n    quiz.appendChild(div);\n    renderMath(div);\n    div.querySelectorAll('.opt').forEach(btn=>btn.onclick=()=>responder(q,btn.dataset.p,div));\n    if(st) reveal(q,div,st.pick);\n  });\n}\nfunction responder(q,pick,div){\n  if(state[q._id])return;\n  let correct;\n  if(q.tipo==='ce'){correct=(pick===q.g);}\n  else{pick=parseInt(pick);correct=(pick===q.g);}\n  state[q._id]={answered:true,correct,pick};\n  reveal(q,div,pick);atualizar();\n}\nfunction reveal(q,div,pick){\n  const opts=div.querySelectorAll('.opt');\n  if(q.tipo==='ce'){\n    opts.forEach(o=>{\n      if(o.dataset.p===q.g)o.classList.add('correct');\n      if(o.dataset.p===pick && pick!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }else{\n    opts.forEach((o,k)=>{\n      if(k===q.g)o.classList.add('correct');\n      if(k===parseInt(pick)&&k!==q.g)o.classList.add('wrong');\n      o.style.pointerEvents='none';\n    });\n  }\n  const cm=div.querySelector('.comment');\n  const ok=state[q._id].correct;\n  const gabtxt=q.tipo==='ce'?(q.g==='C'?'CERTO':'ERRADO'):('Alternativa '+letter(q.g));\n  cm.className=\"comment show \"+(ok?'ok':'no');\n  cm.innerHTML=`<span class=\"res\">${ok?'✔ Você acertou':'✘ Você errou'} · Gabarito: ${gabtxt}</span><span class=\"prof-label\">Resolução do professor</span>${q.cImg?('<img class=\"qimg\" src=\"'+q.cImg+'\" alt=\"resolução\">'):('<div class=\"body\">'+fmt(q.c)+'</div>')}${q.m?('<div class=\"compl\"><span class=\"meu-label\">Complemento (meu)</span><div class=\"body\">'+fmt(q.m)+'</div></div>'):''}`;\n  renderMath(cm);\n}\nfunction atualizar(){\n  const arr=Object.values(state);\n  const resp=arr.length,cert=arr.filter(x=>x.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  document.getElementById('s-resp').textContent=resp;\n  document.getElementById('s-cert').textContent=cert;\n  document.getElementById('s-err').textContent=err;\n  document.getElementById('s-perc').textContent=perc+\"%\";\n  document.getElementById('s-prog').style.width=(resp/Q.length*100)+\"%\";\n}\nfunction reiniciar(){\n  for(const k in state)delete state[k];\n  document.getElementById('analysis').classList.remove('show');\n  atualizar();render();window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction verAnalise(){\n  const arr=Object.entries(state);\n  const box=document.getElementById('analysis');\n  const total=Q.length,resp=arr.length,cert=arr.filter(([,v])=>v.correct).length,err=resp-cert;\n  const perc=resp?Math.round(cert/resp*100):0;\n  const temasList=[...new Set(Q.map(q=>q.t))];\n  const temasMap={};\n  temasList.forEach(tm=>temasMap[tm]={tot:0,cert:0});\n  arr.forEach(([id,v])=>{const q=Q[id];temasMap[q.t].tot++;if(v.correct)temasMap[q.t].cert++;});\n  let bars=\"\";const fracos=[];\n  temasList.forEach(tm=>{\n    const o=temasMap[tm];if(o.tot===0)return;\n    const p=Math.round(o.cert/o.tot*100);\n    const cls=p>=80?'v-forte':p>=60?'v-medio':'v-fraco';\n    const lbl=p>=80?'Forte':p>=60?'Mediano':'Fraco';\n    const cor=p>=80?'var(--green)':p>=60?'var(--yellow-line)':'var(--red)';\n    if(p<60)fracos.push(tm);\n    bars+=`<div class=\"tbar\"><div class=\"tl\"><b>${tm}</b><span>${o.cert}/${o.tot} · ${p}%</span></div>\n      <div class=\"track\"><div class=\"fill\" style=\"width:${p}%;background:${cor}\"></div></div>\n      <div class=\"verdict ${cls}\">${lbl}</div></div>`;\n  });\n  const recom = resp===0 ? `Responda ao menos uma questão para gerar o diagnóstico.` :\n    resp<total ? `Você respondeu ${resp} de ${total} itens. Responda todos para um diagnóstico completo.` :\n    (fracos.length? `Priorize a revisão de: <b>${fracos.join(\", \")}</b>. Reforce a leitura literal e as pegadinhas de certo/errado desses temas no resumo.` :\n    `Excelente! Desempenho consistente em todos os temas. Mantenha a revisão dos pontos quentes.`);\n  box.innerHTML=`<h2>📊 Diagnóstico de desempenho</h2>\n    <div class=\"big\">\n      <div class=\"box\"><b>${resp}</b><span>Respondidas</span></div>\n      <div class=\"box gc\"><b>${cert}</b><span>Acertos</span></div>\n      <div class=\"box ge\"><b>${err}</b><span>Erros</span></div>\n      <div class=\"box\"><b>${perc}%</b><span>Aproveitamento global</span></div>\n    </div>\n    <h3 style=\"margin:6px 0 4px;\">Desempenho por tema</h3>\n    ${bars||'<p class=\"hint\">Responda ao menos uma questão para ver a análise por tema.</p>'}\n    <div class=\"rec\"><b>Recomendação:</b> ${recom}</div>`;\n  box.classList.add('show');\n  box.scrollIntoView({behavior:'smooth'});\n}\nrender();atualizar();renderMath(document.body);\n</script>\n</body>\n</html>\n"}]}};window.EMBEDDED_CONTENT=window.EMBEDDED_CONTENT||{};for(var k in d){window.EMBEDDED_CONTENT[k]=Object.assign({},window.EMBEDDED_CONTENT[k],d[k]);}})();
